const isAr=(language:string)=>language==='ar';
type MainView='overview'|'design'|'engine'|'participants'|'operations'|'judging'|'results'|'enterprise';
type PolicySection='identity'|'registration'|'workflow'|'operations'|'questions'|'judging'|'appeals'|'results'|'certificate'|'privacy';

type Store=ReturnType<typeof useAppStore>;

export const CompetitionOverview: React.FC = () => {
 const store=useAppStore(); const {competition,participants,committees,reviewCases,results,certificates,auditLogs,appeals,language}=store; const ar=isAr(language);
 const policy=getCompetitionPolicy(competition); const readiness=store.getCompetitionReadiness();
 const [view,setView]=useState<MainView>('overview'); const [section,setSection]=useState<PolicySection>('identity'); const [query,setQuery]=useState(''); const [simCount,setSimCount]=useState(Math.max(1,committees.length));
 useEffect(()=>{const open=()=>setView('design');const engine=()=>setView('engine');window.addEventListener('mizan:open-competition-dna',open as EventListener);window.addEventListener('mizan:open-scope-engine',engine as EventListener);return()=>{window.removeEventListener('mizan:open-competition-dna',open as EventListener);window.removeEventListener('mizan:open-scope-engine',engine as EventListener)}},[]);
 const sim=useMemo(()=>store.runSimulation(simCount,30),[simCount,participants.length,committees.length,competition.ruleSet.questionDurationMinutes]);
 const filtered=participants.filter(p=>`${p.code} ${p.fullName} ${p.fullNameArabic} ${localizedCountry(p.country,ar)}`.toLowerCase().includes(query.toLowerCase()));
 const attention=[...readiness.map(i=>({id:i.id,title:ar?i.ar:i.en,kind:'setup'})),...reviewCases.filter(r=>r.status==='pending').slice(0,3).map(r=>({id:r.id,title:ar?`مراجعة ${r.participantCode}`:`Review ${r.participantCode}`,kind:'review'})),...store.incidents.filter(i=>i.status!=='resolved').slice(0,2).map(i=>({id:i.id,title:i.title,kind:'incident'}))];
 const patchPolicy=(mutate:(p:CompetitionPolicy)=>void)=>store.updateCompetitionPolicy(p=>{mutate(p);return p});
 const orgManager=store.currentUser.role==='org_admin'; const leaveCompetition=()=>{window.location.hash='';};
 useEffect(()=>{let alive=true;const sync=async()=>{if(import.meta.env.VITE_REQUIRE_AUTH==='true'&&auth.currentUser){try{const token=await auth.currentUser.getIdToken();const params=new URLSearchParams({competitionId:competition.id});if(store.currentUser.role==='super_admin')params.set('organizationId',competition.organizationId);const response=await fetch(`/api/identity/governance?${params}`,{headers:{authorization:`Bearer ${token}`},cache:'no-store'});const body=await response.json();if(alive&&response.ok)store.syncAuthorizedJudgeProfiles(body.accounts||[],body.grants||[])}catch{/* Keep the last governed profiles during a transient outage. */}}else store.syncAuthorizedJudgeProfiles(store.identityAccounts,store.roleGrants)};void sync();return()=>{alive=false}},[competition.id,competition.organizationId,store.currentUser.role]);
 const nav=[{id:'overview' as const,icon:LayoutDashboard,ar:'اليوم',en:'Overview'},{id:'design' as const,icon:Settings2,ar:'هوية المسابقة',en:'Competition DNA'},{id:'engine' as const,icon:BookMarked,ar:'النطاق والأسئلة',en:'Scope & questions'},{id:'participants' as const,icon:UsersRound,ar:'المشاركون',en:'Participants'},{id:'operations' as const,icon:RadioTower,ar:'التشغيل',en:'Operations'},{id:'judging' as const,icon:Gavel,ar:'التحكيم',en:'Judging'},{id:'results' as const,icon:Award,ar:'النتائج',en:'Results'},{id:'enterprise' as const,icon:ShieldCheck,ar:'المؤسسة',en:'Enterprise'}];
 return <div className="max-w-[1500px] mx-auto px-4 sm:px-6 py-5 sm:py-7"><div className="flex gap-6">
  <aside className="hidden lg:block w-52 shrink-0 pt-1"><div className="sticky top-24 space-y-1"><div className="px-3 mb-4"><div className="text-[10px] font-black tracking-[.16em] text-[#666a67]">{competition.edition}</div><div className="mt-1 text-sm font-extrabold text-[#303733] line-clamp-2">{bilingualName(competition,ar)}</div></div>{nav.map(n=><NavButton key={n.id} active={view===n.id} onClick={()=>setView(n.id)} icon={n.icon} label={ar?n.ar:n.en}/>)}</div></aside>
  <main className="min-w-0 flex-1">
   {orgManager&&<div className="mb-4"><Button size="sm" variant="ghost" onClick={leaveCompetition} icon={<ArrowRight className="w-4 h-4"/>}>{ar?'العودة إلى مسابقات الجهة':'Back to organization competitions'}</Button></div>}
   <div className="lg:hidden mb-4"><div className="mizan-tabs" role="tablist">{nav.map(n=><button key={n.id} role="tab" aria-selected={view===n.id} onClick={()=>setView(n.id)} className={`mizan-tab ${view===n.id?'is-active':''}`}><n.icon className="w-4 h-4"/>{ar?n.ar:n.en}</button>)}</div></div>
   <SurfaceBoundary ar={ar} label={ar?'هذا القسم':'This section'}>
   {view==='overview'&&<Overview store={store} ar={ar} attention={attention} readiness={readiness} onConfigure={()=>setView('design')}/>} 
   {view==='design'&&<CompetitionDNA store={store} ar={ar} policy={policy} section={section} setSection={setSection} patchPolicy={patchPolicy}/>} 
   {view==='engine'&&<QuestionEngineWorkspace/>} 
   {view==='participants'&&<ParticipantsView store={store} ar={ar} query={query} setQuery={setQuery} filtered={filtered}/>} 
   {view==='operations'&&<OperationsView mode="operations" store={store} ar={ar} sim={sim} simCount={simCount} setSimCount={setSimCount} attention={attention}/>}
   {view==='judging'&&<><div className="mb-5"><div className="mizan-kicker">{ar?'إدارة التحكيم':'JUDGING MANAGEMENT'}</div><h1 className="mt-1 text-2xl font-black">{ar?'اللجان والمحكمون في مكان واحد':'Panels and judges in one place'}</h1><p className="mt-1 text-xs leading-6 text-[#666c68]">{ar?'كوّن اللجان، اختر رؤساءها، ووزّع المحكمين المخوّلين لهذه المسابقة.':'Build panels, choose their chairs, and assign judges authorized for this competition.'}</p></div><OperationsView mode="judging" store={store} ar={ar} sim={sim} simCount={simCount} setSimCount={setSimCount} attention={attention}/></>}
   {view==='results'&&<ResultsView store={store} ar={ar}/>} 
   {view==='enterprise'&&<EnterpriseWorkspace/>} 
   </SurfaceBoundary>
  </main>
 </div></div>;
};

const Overview=({store,ar,attention,readiness,onConfigure}:{store:Store;ar:boolean;attention:any[];readiness:any[];onConfigure:()=>void})=>{
 const {competition,participants,committees,sealApprovals}=store; const canPublish=['draft','configured'].includes(competition.status); const publicPageReady=!canPublish; const [publishIssues,setPublishIssues]=useState<string[]>([]); const [publishSuccess,setPublishSuccess]=useState(false);
 const publish=async()=>{setPublishSuccess(false);try{const out=await store.publishCompetition();if(out.ok){setPublishIssues([]);setPublishSuccess(true);window.setTimeout(()=>{window.location.hash=`competition?comp=${competition.id}`},80)}else setPublishIssues(out.issues||[ar?'تعذر فتح المسابقة.':'Could not open competition.'])}catch{setPublishIssues([ar?'تعذر فتح المسابقة. أعد المحاولة بعد التحقق من الاتصال.':'Could not open competition. Check the connection and try again.'])}};
 return <div className="space-y-5">
  <section className="mizan-surface p-6 sm:p-8"><div className="flex flex-col md:flex-row md:items-end justify-between gap-5"><div><div className="flex flex-wrap items-center gap-2"><Badge>{uiToken(competition.status,ar)}</Badge><Badge variant="neutral" dot={false}>{uiToken(competition.automationLevel,ar)}</Badge></div><h1 className="mizan-title text-3xl sm:text-4xl font-black mt-3">{bilingualName(competition,ar)}</h1><p className="mizan-muted text-sm mt-2">{competition.venueName||'—'} · {competition.startDate||'—'}</p></div><div className="flex flex-wrap gap-2"><Button onClick={onConfigure} variant="outline" icon={<Settings2 className="w-4 h-4"/>}>{ar?'ضبط':'Configure'}</Button>{canPublish&&<Button onClick={()=>void publish()} icon={<Activity className="w-4 h-4"/>}>{ar?'فتح المسابقة':'Open competition'}</Button>}{publicPageReady&&<Button onClick={()=>{window.location.hash=`#competition?comp=${encodeURIComponent(competition.id)}`}} icon={<Globe2 className="w-4 h-4"/>}>{ar?'صفحة المسابقة':'Competition page'}</Button>}</div></div>{publishSuccess&&<div role="status" className="mt-5 rounded-xl bg-[#E7EEE9] text-[#214C40] p-3 text-xs font-bold">{ar?'تم فتح المسابقة ونشر واجهتها العامة بنجاح.':'Competition is open and its public page is published.'}</div>}{publishIssues.length>0&&<div role="status" className="mt-5 rounded-xl bg-[#F2EADC] text-[#725630] p-3 text-xs font-bold"><div>{ar?'قبل فتح المسابقة أكمل التالي:':'Complete these before opening the competition:'}</div><ul className="mt-2 list-disc list-inside space-y-1">{publishIssues.map(x=><li key={x}>{x}</li>)}</ul></div>}</section>
  {publicPageReady&&<section><ShareRegistration c={competition} ar={ar}/></section>}
  <section className="grid grid-cols-3 gap-3"><MetricCard icon={UsersRound} value={participants.length} label={ar?'مشارك':'Participants'}/><MetricCard icon={Clock3} value={participants.filter(p=>p.status==='in_queue').length} label={ar?'في الانتظار':'Waiting'}/><MetricCard icon={Gavel} value={committees.filter(c=>c.status!=='offline').length} label={ar?'لجان نشطة':'Active panels'}/></section>
  <section className="grid xl:grid-cols-[1.35fr_.65fr] gap-4 [&>*]:min-w-0">
   <div className="mizan-surface p-5 sm:p-6"><div className="flex items-center justify-between gap-3"><div><div className="mizan-kicker">{ar?'مسار المسابقة':'LIVE FLOW'}</div><h2 className="font-extrabold mt-1">{ar?'من التسجيل إلى الشهادة':'Registration to certificate'}</h2></div><Badge variant={readiness.length?'amber':'emerald'}>{readiness.length?`${readiness.length} ${ar?'ملاحظات':'items'}`:(ar?'جاهز':'Ready')}</Badge></div><div className="flex items-start gap-2 overflow-x-auto mt-5 pb-1">{getCompetitionPolicy(store.competition).workflow.filter(w=>w.enabled).map((w,i,all)=><React.Fragment key={w.id}><div className="shrink-0 w-14 text-center"><div title={workflowLabel(w.id,ar)} className={`mx-auto w-9 h-9 rounded-xl grid place-items-center text-xs font-black ${w.automated?'bg-[#E7EEE9] text-[#214C40]':'bg-[#F2EADC] text-[#7d5e34]'}`}>{i+1}</div><div className="mt-1.5 text-[9px] sm:text-[10px] font-bold text-[#59615c] leading-4 whitespace-nowrap">{workflowLabel(w.id,ar)}</div></div>{i<all.length-1&&<div className="shrink-0 w-4 h-px bg-[#d9d7d0] mt-[18px]"/>}</React.Fragment>)}</div><div className="mt-4 text-xs text-[#626864]">{ar?'الأخضر مؤتمت · الذهبي قرار بشري':'Green automated · gold human decision'}</div>{getCompetitionPolicy(store.competition).results.requireDualApprovalToSeal&&sealApprovals.length>0&&<div className="text-[11px] text-[#7d5e34] mt-3">{ar?`اعتمادات الختم الحالية: ${new Set(sealApprovals.map(a=>a.actorId)).size}/2`:`Seal approvals: ${new Set(sealApprovals.map(a=>a.actorId)).size}/2`}</div>}</div>
   <div className="mizan-surface p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="mizan-kicker">{ar?'يحتاج انتباهك':'NEEDS ATTENTION'}</div><h2 className="font-extrabold mt-1">{attention.length}</h2></div><CircleAlert className={`w-5 h-5 ${attention.length?'text-[#89673a]':'text-[#2F6555]'}`}/></div><div className="mt-4">{attention.length?attention.slice(0,5).map(x=><div key={x.id} className="py-2.5 border-b border-[#ebe9e3] last:border-0 text-xs font-semibold text-[#454c48]">{x.title}</div>):<div className="py-6 text-center"><BadgeCheck className="w-6 h-6 text-[#2F6555] mx-auto"/><div className="text-xs font-bold mt-2">{ar?'لا شيء يحتاج تدخلك':'Nothing needs intervention'}</div></div>}</div></div>
  </section>
 </div>;
};

const CompetitionDNA=({store,ar,policy,section,setSection,patchPolicy}:{store:Store;ar:boolean;policy:CompetitionPolicy;section:PolicySection;setSection:(s:PolicySection)=>void;patchPolicy:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const {competition}=store; const sections:[PolicySection,React.ComponentType<{className?:string}>,string][]=[['identity',Fingerprint,ar?'الهوية والفئات':'Identity & categories'],['registration',FileCheck2,ar?'التسجيل والشروط':'Registration'],['workflow',Network,ar?'المسار':'Workflow'],['operations',QrCode,ar?'التشغيل':'Operations'],['questions',Sparkles,ar?'الأسئلة':'Questions'],['judging',Gavel,ar?'التحكيم':'Judging'],['appeals',ListChecks,ar?'الاعتراضات':'Appeals'],['results',LockKeyhole,ar?'النتائج':'Results'],['certificate',Award,ar?'الشهادة':'Certificates'],['privacy',ShieldCheck,ar?'الخصوصية':'Privacy']];
 return <div className="space-y-4">
  <div><div className="mizan-kicker">{ar?'بصمة المسابقة':'MIZAN COMPETITION DNA'}</div><h1 className="text-2xl sm:text-3xl font-black mt-1">{ar?'كل مسابقة لها نظامها':'Every competition is its own system'}</h1><p className="text-sm text-[#626864] mt-2 max-w-2xl">{ar?'لا توجد لائحة عالمية مفروضة. كل شرط وكل زر تحكيم وكل مرحلة تخص هذه المسابقة وحدها.':'No global rules are imposed. Registration, judging actions, workflow and policies belong to this competition only.'}</p></div>
  <div className="grid lg:grid-cols-[220px_minmax(0,1fr)] gap-4 min-w-0">
   <div className="mizan-surface p-2 h-fit"><div className="grid grid-cols-2 lg:grid-cols-1 gap-1">{sections.map(([id,Icon,label])=><button key={id} onClick={()=>setSection(id)} className={`flex items-center gap-2 px-3 py-2.5 rounded-xl text-xs sm:text-sm font-bold text-start ${section===id?'bg-[#E7EEE9] text-[#214C40]':'text-[#626a65] hover:bg-[#f2f0ea]'}`}><Icon className="w-4 h-4 shrink-0"/><span className="truncate min-w-0">{label}</span></button>)}</div></div>
   <div className="mizan-surface p-5 sm:p-7 min-h-[520px] min-w-0 max-w-full overflow-x-clip">
    {section==='identity'&&<IdentitySection store={store} ar={ar}/>} 
    {section==='registration'&&<RegistrationSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='workflow'&&<WorkflowSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='operations'&&<OperationsPolicySection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='questions'&&<QuestionsSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='judging'&&<JudgingSection store={store} ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='appeals'&&<AppealsSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='results'&&<ResultPolicySection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='certificate'&&<CertificateSection store={store} ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='privacy'&&<PrivacySection ar={ar} policy={policy} patch={patchPolicy}/>} 
   </div>
  </div>
 </div>;
};

const quarterLabel=(units:number,ar:boolean)=>{const n=Math.max(1,Math.round(units));const whole=Math.floor(n/4),rem=n%4;const frac=['','¼','½','¾'][rem];if(!whole)return frac;return ar?`${whole}${frac?` و${frac}`:''} ${whole===1?'وجه':'أوجه'}`:`${whole}${frac?` ${frac}`:''} page${whole===1?'':'s'}`};
const legacyQuarterUnits=(cat:Category)=>cat.pageQuarterUnits||({quarter:1,third:1,half:2,full:4} as Record<string,number>)[cat.pagePortion||'']||1;
/*
 * نطاق الحفظ لم يعد رقمًا يُكتب باليد.
 *
 * «عشرة أجزاء» لا تحدد أي عشرة، فكان الرقم يصل إلى السحب بوصفه حدًّا أعلى للجزء فيُسأل
 * المتسابق مما لم يحفظ. الحقل هنا صار عرضًا للنطاق الحقيقي وبابًا إلى الشاشة التي ترسمه.
 */
const ScopeHandoff=({ar,label,category}:{ar:boolean;label:string;category?:Category})=>{
 const scope=category?categoryScopeOf(category):null;
 const defined=!!scope&&scopeAyahCount(scope)>0;
 const metrics=defined?scopeMetrics(scope!):null;
 return <Control label={label}>
  <div className="rounded-xl border border-[#dcdad2] bg-white p-3">
   <div className="flex items-start justify-between gap-2">
    <div className="min-w-0">
     <div className="text-xs font-black text-[#24302b] truncate">{defined?describeScope(scope!,ar):(ar?'لم يُحدَّد بعد':'Not defined yet')}</div>
     <div className="text-[10px] text-[#696f6b] mt-0.5">{metrics?(ar?`${metrics.ayahCount} آية · ${metrics.fullJuz.length} جزءًا كاملًا · ${metrics.segmentCount} مقطعًا`:`${metrics.ayahCount} ayat · ${metrics.fullJuz.length} complete juz · ${metrics.segmentCount} segments`):(ar?'يُحدَّد النطاق بالأجزاء أو السور أو حدود الآيات في شاشة النطاق والأسئلة.':'Set it by juz, surah or ayah bounds in the scope screen.')}</div>
    </div>
    <Button size="sm" variant="outline" onClick={()=>window.dispatchEvent(new CustomEvent('mizan:open-scope-engine'))}>{defined?(ar?'تعديل':'Edit'):(ar?'تحديد':'Define')}</Button>
   </div>
  </div>
 </Control>;
};

const PassageLengthControl=({ar,mode,value,onMode,onValue}:{ar:boolean;mode:'ayat'|'page_quarters';value:number;onMode:(v:'ayat'|'page_quarters')=>void;onValue:(v:number)=>void})=><Control label={ar?'طول مقطع السؤال':'Question passage length'}><div className="rounded-xl border border-[#dcdad2] bg-white p-2"><div className="grid grid-cols-2 gap-1"><button type="button" onClick={()=>onMode('ayat')} className={`min-h-10 rounded-lg text-xs font-black ${mode==='ayat'?'bg-[#214C40] text-white':'bg-[#f3f1eb] text-[#626a65]'}`}>{ar?'بالآيات':'By ayat'}</button><button type="button" onClick={()=>onMode('page_quarters')} className={`min-h-10 rounded-lg text-xs font-black ${mode==='page_quarters'?'bg-[#214C40] text-white':'bg-[#f3f1eb] text-[#626a65]'}`}>{ar?'بالأوجه':'By pages'}</button></div><div className="mt-2 flex items-center justify-between gap-3"><button type="button" aria-label={ar?'إنقاص':'Decrease'} onClick={()=>onValue(Math.max(1,value-1))} className="w-11 h-11 rounded-xl border border-[#dcdad2] text-xl font-black">−</button><div className="min-w-0 flex-1 text-center"><div className="text-lg font-black tabular-nums">{mode==='ayat'?value:quarterLabel(value,ar)}</div><div className="text-[10px] text-[#656b66]">{mode==='ayat'?(ar?'آية لكل سؤال':'ayat per question'):(ar?'الزيادة كل مرة: ربع وجه':'increments by quarter page')}</div></div><button type="button" aria-label={ar?'زيادة':'Increase'} onClick={()=>onValue(value+1)} className="w-11 h-11 rounded-xl border border-[#dcdad2] text-xl font-black">+</button></div></div></Control>;

/*
 * حالة الحفظ.
 *
 * نموذج هوية المسابقة يحفظ عند كل ضغطة مفتاح: لا زر حفظ، ولا مؤشر، ولا سطح يظهر فيه الفشل.
 * فالمستخدم يكتب اسم مسابقته ولا يعلم أوصل شيء أم لا، ويغادر الصفحة على أمل.
 *
 * وهذا المؤشر لا يطمئن من تلقاء نفسه: يقرأ حالة الحفظ الحقيقية. خطأ الكتابة المحلية يظهر
 * أحمر، ووضع القاعة يقول إن الحفظ على الجهاز والرفع مؤجَّل، ولا يقال «حُفظ» إلا حين لا يكون
 * هناك عطل ولا تأجيل.
 */
const SaveState=({store,ar}:{store:Store;ar:boolean})=>{
 const error=store.persistenceError;
 const at=store.competitionConfigUpdatedAt;
 const time=at?new Date(at).toLocaleTimeString(ar?'ar-KW-u-nu-latn':'en-US',{hour:'2-digit',minute:'2-digit'}):'';
 if(error)return <span role="alert" className="inline-flex items-center gap-1.5 rounded-full bg-[#F6E7E7] px-3 py-1.5 text-[10px] font-black text-[#7A2E2E]"><AlertTriangle className="w-3.5 h-3.5"/>{ar?(error.code==='QUOTA_EXCEEDED'?'ذاكرة المتصفح ممتلئة — لم يُحفظ':'تعذّر الحفظ على هذا الجهاز'):'Not saved'}</span>;
 if(store.isOffline)return <span role="status" className="inline-flex items-center gap-1.5 rounded-full bg-[#F5EDE2] px-3 py-1.5 text-[10px] font-black text-[#7a5a2f]"><WifiOff className="w-3.5 h-3.5"/>{ar?'محفوظ على الجهاز — يُرفع عند عودة الاتصال':'Saved locally — will upload'}</span>;
 return <span role="status" className="inline-flex items-center gap-1.5 rounded-full bg-[#E7EEE9] px-3 py-1.5 text-[10px] font-black text-[#214C40]"><Check className="w-3.5 h-3.5"/>{ar?(time?`حُفظ ${time}`:'يُحفظ تلقائيًا'):(time?`Saved ${time}`:'Saves automatically')}</span>;
};

const IdentitySection=({store,ar}:{store:Store;ar:boolean})=>{
 const c=store.competition;
 const [selected,setSelected]=useState(c.categories[0]?.id||'');
 const cat=c.categories.find(x=>x.id===selected);
 const [adding,setAdding]=useState(false);
 const [identityTab,setIdentityTab]=useState<'info'|'categories'|'share'>('info');
 const identityTabAnchor=useTabAnchor(identityTab);
 const emptyDraft=()=>({nameArabic:'',name:'',riwaya:'',memorizationScope:'',juzCount:'',passageMode:'ayat' as 'ayat'|'page_quarters',passageValue:1,minAge:'',maxAge:'',genderConstraint:'all' as 'all'|'male'|'female'});
 const [draft,setDraft]=useState(emptyDraft());
 useEffect(()=>{if(!selected&&c.categories[0])setSelected(c.categories[0].id);if(selected&&!c.categories.some(x=>x.id===selected))setSelected(c.categories[0]?.id||'')},[c.categories,selected]);
 const patch=(p:Partial<Competition>)=>store.updateCompetitionDetails(p);
 const patchCat=(p:Partial<Category>)=>cat&&store.updateCategory(cat.id,p);
 const saveCategory=()=>{if(!draft.nameArabic.trim()&&!draft.name.trim())return;const passage=draft.passageMode==='ayat'?{passageMode:'ayat' as const,ayatPerQuestion:Math.max(1,draft.passageValue),pageQuarterUnits:undefined,pagePortion:undefined}:{passageMode:'page_quarters' as const,pageQuarterUnits:Math.max(1,draft.passageValue),ayatPerQuestion:undefined,pagePortion:undefined};const x=store.addCategory({nameArabic:draft.nameArabic.trim()||draft.name.trim(),name:draft.name.trim()||draft.nameArabic.trim(),riwaya:draft.riwaya.trim(),memorizationScope:draft.memorizationScope.trim(),juzCount:Number(draft.juzCount)||0,targetDurationMinutes:c.ruleSet.questionDurationMinutes||8,minAge:Number(draft.minAge)>0?Number(draft.minAge):undefined,maxAge:Number(draft.maxAge)>0?Number(draft.maxAge):undefined,genderConstraint:draft.genderConstraint,...passage});setSelected(x.id);setDraft(emptyDraft());setAdding(false)};
 const [logoBusy,setLogoBusy]=useState(false); const [logoError,setLogoError]=useState(''); const visibleLogo=c.logoUrl&&!c.logoUrl.startsWith('data:')?c.logoUrl:undefined;
 const uploadLogo=async(file?:File)=>{if(!file||logoBusy)return;setLogoError('');setLogoBusy(true);try{const url=await uploadCompetitionLogo(c.organizationId,c.id,file);patch({logoUrl:url})}catch(err){const code=err instanceof Error?err.message:'';
  /* كان كل فشل — انقطاع شبكة، رفض صلاحية، تخزين غير مهيّأ — يُقال للمستخدم إن صيغة ملفه خاطئة. */
  setLogoError(code==='LOGO_TOO_LARGE'?(ar?'حجم الشعار يجب ألا يتجاوز 2 ميغابايت.':'Logo must be 2MB or smaller.')
   :code==='LOGO_TYPE_UNSUPPORTED'?(ar?'اختر ملف PNG أو JPG أو WebP أو SVG.':'Choose a PNG, JPG, WebP or SVG file.')
   :serverErrorLabel(code,ar))}finally{setLogoBusy(false)}};
 const removeLogo=async()=>{if(logoBusy)return;setLogoError('');setLogoBusy(true);try{if(isManagedBrandLogoUrl(c.logoUrl))await deleteCompetitionLogo(c.organizationId,c.id);patch({logoUrl:undefined})}catch{setLogoError(ar?'تعذّر حذف ملف الشعار من التخزين. أعد المحاولة بعد قليل.':'Could not remove the stored logo. Try again shortly.')}finally{setLogoBusy(false)}};
 const catMode: 'ayat'|'page_quarters'=cat?.passageMode||(cat?.pageQuarterUnits||cat?.pagePortion?'page_quarters':'ayat');
 const catPassageValue=cat?(catMode==='ayat'?Math.max(1,cat.ayatPerQuestion||1):legacyQuarterUnits(cat)):1;
 return <div className="space-y-6"><div className="flex flex-wrap items-start justify-between gap-3"><SectionTitle title={ar?'هوية المسابقة':'Competition identity'} subtitle={ar?'بيانات المسابقة في الأعلى، والفئات تُضاف وتحفظ بشكل مستقل في الأسفل.':'Competition details are above; categories are added and saved independently below.'}/><SaveState store={store} ar={ar}/></div>
  {logoError&&<div role="alert" className="rounded-xl bg-[#f7ece9] px-4 py-3 text-xs font-bold text-[#874b43] mb-3">{logoError}</div>}
  {/* تسعة حقول هوية كانت تسبق إدارة الفئات في عمود واحد؛ التبويب يجعل كل مهمة شاشة. */}
  <div role="tablist" ref={identityTabAnchor} aria-label={ar?'أقسام الهوية':'Identity sections'} className="mizan-tabs">
   {([['info',ar?'بيانات المسابقة':'Competition details'],['categories',ar?`الفئات (${c.categories.length})`:`Categories (${c.categories.length})`],['share',ar?'رابط التسجيل':'Registration link']] as const).map(([id,label])=><button key={id} type="button" role="tab" aria-selected={identityTab===id} onClick={()=>setIdentityTab(id)} className={`mizan-tab ${identityTab===id?'is-active':''}`}>{label}</button>)}
  </div>
  {identityTab==='info'&&<>
  <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 [&>*]:min-w-0"><TextControl kind="arabic" label={ar?'الاسم بالعربية':'Arabic name'} value={c.nameArabic} onChange={v=>patch({nameArabic:v})}/><TextControl kind="latin" label={ar?'الاسم بالإنجليزية':'English name'} value={c.name} onChange={v=>patch({name:v})}/><TextControl label={ar?'المنطقة الزمنية':'Timezone'} value={c.timezone} onChange={v=>patch({timezone:v})}/><TextControl label={ar?'المكان':'Venue'} value={c.venueName} onChange={v=>patch({venueName:v})}/><TextControl type="date" label={ar?'بداية المسابقة':'Start date'} value={c.startDate} onChange={v=>patch({startDate:v})}/><TextControl type="date" label={ar?'نهاية المسابقة':'End date'} value={c.endDate} onChange={v=>patch({endDate:v})}/><Control label={ar?'الأتمتة':'Automation'}><TinySelect value={c.automationLevel} onChange={v=>patch({automationLevel:v as any})}><option value="assisted">{automationLevelLabel('assisted',ar)}</option><option value="automated">{automationLevelLabel('automated',ar)}</option><option value="autopilot">{automationLevelLabel('autopilot',ar)}</option></TinySelect></Control><TextControl kind={ar?'arabic':'latin'} label={ar?'اسم العلامة لهذه المسابقة':'Wordmark for this competition'} value={ar?(c.displayNameArabic||''):(c.displayName||'')} onChange={v=>patch(ar?{displayNameArabic:v||undefined}:{displayName:v||undefined})}/><Control label={ar?'شعار هذه المسابقة':'Competition logo'}><div className="rounded-xl border border-[#dcdad2] bg-white p-3"><div className="flex flex-col sm:flex-row sm:items-center gap-3">{visibleLogo?<img src={visibleLogo} alt={ar?'شعار المسابقة':'Competition logo'} className="w-16 h-16 rounded-xl object-contain border bg-white"/>:<div className="w-16 h-16 rounded-xl border border-dashed grid place-items-center text-[10px] text-[#777]">{ar?'لا شعار':'No logo'}</div>}<label aria-disabled={logoBusy} className={`min-h-11 px-4 rounded-xl bg-[#214C40] text-white text-xs font-black inline-flex items-center justify-center gap-2 cursor-pointer ${logoBusy?'opacity-60 pointer-events-none':''}`}><FileUp className="w-4 h-4"/>{logoBusy?(ar?'جارٍ الحفظ…':'Saving…'):(visibleLogo?(ar?'استبدال الشعار':'Replace logo'):(ar?'رفع الشعار':'Upload logo'))}<input type="file" accept=".png,.jpg,.jpeg,.webp,.svg,image/png,image/jpeg,image/webp,image/svg+xml" className="sr-only" onChange={e=>{void uploadLogo(e.target.files?.[0]);e.currentTarget.value=''}}/></label>{c.logoUrl&&<button type="button" disabled={logoBusy} onClick={()=>void removeLogo()} className="min-h-11 px-4 rounded-xl border text-xs font-black disabled:opacity-50">{ar?'حذف':'Remove'}</button>}</div><p className="mt-2 text-[10px] text-[#656b66]">{ar?'PNG أو JPG/JPEG أو WebP أو SVG — بحد أقصى 2MB. يُحفظ الملف في التخزين الفعلي ولا يُخزن داخل بيانات المسابقة.':'PNG, JPG/JPEG, WebP or SVG — max 2MB. The file is stored in object storage, never inside competition state.'}</p></div></Control></div>
  </>}
  {identityTab==='categories'&&<>
  <div className="border-t border-[#e5e3dc] pt-5"><div className="flex items-center justify-between gap-3"><div><div className="text-sm font-black">{ar?'الفئات':'Categories'}</div><p className="text-[10px] text-[#656b66] mt-1">{ar?'لا توجد فئة افتراضية. أضف الفئة التي تريدها ثم احفظها.':'There is no default category. Add the category you need, then save it.'}</p></div><button type="button" onClick={()=>setAdding(true)} className="min-h-11 px-3 rounded-xl inline-flex items-center gap-1 text-xs font-black text-[#214C40] border border-[#cddbd3] bg-white"><Plus className="w-4 h-4"/>{ar?'فئة':'Category'}</button></div>{!c.categories.length&&!adding&&<div className="mt-4 rounded-xl bg-[#f7f5ef] p-5 text-center text-xs text-[#656b66]">{ar?'لا توجد فئات بعد. اضغط «+ فئة» لإضافة الأولى.':'No categories yet. Press “+ Category” to add the first one.'}</div>}{c.categories.length>0&&<div className="mizan-tabs mizan-tabs-sub mt-3" role="tablist">{c.categories.map(x=><button key={x.id} role="tab" aria-selected={selected===x.id&&!adding} onClick={()=>{setSelected(x.id);setAdding(false)}} className={`mizan-tab ${selected===x.id&&!adding?'is-active':''}`}>{ar?x.nameArabic:x.name}</button>)}</div>}</div>
  {adding&&<div className="rounded-2xl border border-[#cddbd3] bg-[#F7FAF8] p-4 sm:p-5 space-y-4"><div className="text-sm font-black">{ar?'إضافة فئة جديدة':'Add new category'}</div><div className="grid grid-cols-1 xl:grid-cols-2 gap-3 [&>*]:min-w-0"><TextControl kind="arabic" label={ar?'اسم الفئة عربي':'Arabic category'} value={draft.nameArabic} onChange={v=>setDraft(d=>({...d,nameArabic:v}))}/><TextControl kind="latin" label={ar?'اسم الفئة إنجليزي':'English category'} value={draft.name} onChange={v=>setDraft(d=>({...d,name:v}))}/><TextControl kind="arabic" label={ar?'الرواية / القراءة':'Riwaya / Qira’a'} value={draft.riwaya} onChange={v=>setDraft(d=>({...d,riwaya:v}))}/><ScopeHandoff ar={ar} label={ar?'نطاق الحفظ':'Memorization range'}/><PassageLengthControl ar={ar} mode={draft.passageMode} value={draft.passageValue} onMode={v=>setDraft(d=>({...d,passageMode:v,passageValue:1}))} onValue={v=>setDraft(d=>({...d,passageValue:v}))}/><DraftNumber label={ar?'العمر الأدنى':'Minimum age'} max={100} value={draft.minAge} onChange={v=>setDraft(d=>({...d,minAge:v}))}/><DraftNumber label={ar?'العمر الأعلى':'Maximum age'} max={100} value={draft.maxAge} onChange={v=>setDraft(d=>({...d,maxAge:v}))}/><Control label={ar?'الجنس حسب الشروط':'Gender constraint'}><TinySelect value={draft.genderConstraint} onChange={v=>setDraft(d=>({...d,genderConstraint:v as any}))}><option value="all">{ar?'الكل':'All'}</option><option value="male">{ar?'رجال':'Male'}</option><option value="female">{ar?'نساء':'Female'}</option></TinySelect></Control></div><div className="rounded-xl bg-[#f0eee8] px-3 py-2 text-[10px] text-[#656b66]">{ar?'عدد الأسئلة والزمن التشغيلي يُداران داخليًا من سياسة المسابقة ولا يثقلان نموذج الفئة.':'Question count and operational timing are managed internally by competition policy, not by this category form.'}</div><div className="flex justify-end gap-2"><Button size="sm" variant="ghost" onClick={()=>{setDraft(emptyDraft());setAdding(false)}}>{ar?'إلغاء':'Cancel'}</Button><Button size="sm" disabled={!draft.nameArabic.trim()&&!draft.name.trim()} onClick={saveCategory}>{ar?'حفظ الفئة':'Save category'}</Button></div></div>}
  {!adding&&cat&&<div className="rounded-2xl bg-[#f4f2ec] p-4 sm:p-5 space-y-4"><div className="grid grid-cols-1 xl:grid-cols-2 gap-3 [&>*]:min-w-0"><TextControl kind="arabic" label={ar?'اسم الفئة عربي':'Arabic category'} value={cat.nameArabic} onChange={v=>patchCat({nameArabic:v})}/><TextControl kind="latin" label={ar?'اسم الفئة إنجليزي':'English category'} value={cat.name} onChange={v=>patchCat({name:v})}/><TextControl kind="arabic" label={ar?'الرواية / القراءة':'Riwaya / Qira’a'} value={cat.riwaya} onChange={v=>patchCat({riwaya:v})}/><ScopeHandoff ar={ar} label={ar?'نطاق الحفظ':'Memorization range'} category={cat}/><PassageLengthControl ar={ar} mode={catMode} value={catPassageValue} onMode={v=>patchCat(v==='ayat'?{passageMode:'ayat',ayatPerQuestion:1,pageQuarterUnits:undefined,pagePortion:undefined}:{passageMode:'page_quarters',pageQuarterUnits:1,ayatPerQuestion:undefined,pagePortion:undefined})} onValue={v=>patchCat(catMode==='ayat'?{passageMode:'ayat',ayatPerQuestion:v,pageQuarterUnits:undefined,pagePortion:undefined}:{passageMode:'page_quarters',pageQuarterUnits:v,ayatPerQuestion:undefined,pagePortion:undefined})}/><NumberControl label={ar?'العمر الأدنى':'Minimum age'} max={100} value={cat.minAge||0} onChange={v=>patchCat({minAge:v||undefined})}/><NumberControl label={ar?'العمر الأعلى':'Maximum age'} max={100} value={cat.maxAge||0} onChange={v=>patchCat({maxAge:v||undefined})}/><Control label={ar?'الجنس حسب الشروط':'Gender constraint'}><TinySelect value={cat.genderConstraint||'all'} onChange={v=>patchCat({genderConstraint:v as any})}><option value="all">{ar?'الكل':'All'}</option><option value="male">{ar?'رجال':'Male'}</option><option value="female">{ar?'نساء':'Female'}</option></TinySelect></Control></div><div className="flex flex-col items-end gap-2">{store.participants.some(p=>p.categoryId===cat.id)&&<p className="text-[10px] leading-5 text-[#696f6b] text-end">{ar?`لا تُحذف فئة مسجَّل فيها متسابقون (${store.participants.filter(p=>p.categoryId===cat.id).length}). انقلهم إلى فئة أخرى أولًا.`:`A category with registered participants (${store.participants.filter(p=>p.categoryId===cat.id).length}) cannot be removed. Move them to another category first.`}</p>}<Button size="sm" variant="ghost" disabled={store.participants.some(p=>p.categoryId===cat.id)} onClick={()=>{if(store.removeCategory(cat.id))setSelected(c.categories.find(x=>x.id!==cat.id)?.id||'')}} icon={<Trash2 className="w-4 h-4"/>}>{ar?'حذف الفئة':'Remove category'}</Button></div></div>}
  </>}
  {identityTab==='share'&&<ShareRegistration c={c} ar={ar}/>}
 </div>;
};
const DraftNumber=({label,value,onChange,max}:{label:string;value:string;onChange:(v:string)=>void;max?:number})=><Control label={label}><input type="number" min="0" max={max} value={value} onChange={e=>{const raw=e.target.value.replace(/[^0-9.]/g,'');if(max===undefined||raw===''){onChange(raw);return}const n=Number(raw);onChange(Number.isFinite(n)&&n>max?String(max):raw)}} className="mizan-input text-sm font-semibold" dir="ltr"/></Control>;

const RegistrationSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'التسجيل والشروط':'Registration & rules'} subtitle={ar?'المتسابق يرى فقط الحقول والشروط التي تحتاجها هذه المسابقة.':'Participants see only the fields and rules used by this competition.'}/><div className="mizan-surface-soft px-4"><Toggle value={policy.registration.autoApproveEligible} onChange={v=>patch(p=>{p.registration.autoApproveEligible=v})} label={ar?'اعتماد تلقائي إذا استوفى الشروط':'Auto-approve when rules are met'}/><Toggle value={policy.registration.requireGuardianForMinors} onChange={v=>patch(p=>{p.registration.requireGuardianForMinors=v})} label={ar?'ولي أمر للقاصر':'Guardian for minors'}/></div><div><div className="text-xs font-black text-[#606662] mb-2">{ar?'حقول التسجيل':'Registration fields'}</div><div className="divide-y divide-[#e5e3dc] border-y border-[#e5e3dc]">{policy.registration.fields.map((f,i)=><RegistrationFieldRow key={f.id} f={f} ar={ar} onVisible={v=>patch(p=>{p.registration.fields[i].visible=v})} onRequired={v=>patch(p=>{p.registration.fields[i].required=v})}/>)}</div></div><div className="rounded-xl bg-[#F2EADC] text-[#725630] p-3 text-xs">{ar?'شروط الفئة مثل العمر والجنس والنطاق تُطبّق فوق هذه الحقول، وأي حالة غير محسومة تذهب للمراجعة البشرية.':'Category rules such as age, gender and scope apply on top of these fields; unresolved cases go to human review.'}</div></div>;

const WorkflowSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'المسار والأتمتة':'Workflow & automation'} subtitle={ar?'كل مرحلة يمكن تشغيلها أو أتمتتها أو اشتراط اعتماد بشري.':'Each stage can be enabled, automated, or approval-gated.'}/><div className="divide-y divide-[#e6e4dd]">{policy.workflow.map((w,i)=><div key={w.id} className="py-3 grid grid-cols-[36px_1fr_auto] items-center gap-3"><span className="w-8 h-8 rounded-xl bg-[#f0eee8] grid place-items-center text-xs font-black">{i+1}</span><div><div className="text-sm font-bold">{workflowLabel(w.id,ar)}</div><div className="text-[11px] text-[#666b67]">{!w.enabled?(ar?'متوقف':'Disabled'):w.automated?(ar?'آلي':'Automated'):(ar?'بشري':'Human')}</div></div><div className="flex gap-1"><Chip active={w.enabled} onClick={()=>patch(p=>{p.workflow[i].enabled=!p.workflow[i].enabled})}>{w.enabled?(ar?'مفعّل':'On'):(ar?'متوقف':'Off')}</Chip>{w.enabled&&<Chip active={w.automated} amber={!w.automated} onClick={()=>patch(p=>{p.workflow[i].automated=!p.workflow[i].automated})}>{w.automated?(ar?'آلي':'Auto'):(ar?'بشري':'Human')}</Chip>}{w.enabled&&<Chip active={w.requiresApproval} amber onClick={()=>patch(p=>{p.workflow[i].requiresApproval=!p.workflow[i].requiresApproval})}>{ar?'اعتماد':'Approval'}</Chip>}</div></div>)}</div></div>;

/* مشاركة رابط تسجيل هذه المسابقة: رابط مباشر (#register?comp=..) + رمز QR للطباعة/النشر. */
const ShareRegistration:React.FC<{c:Competition;ar:boolean}>=({c,ar})=>{
 const [copied,setCopied]=useState(false);
 const origin=typeof window!=='undefined'?window.location.origin:'';
 const link=`${origin}/#register?comp=${c.id}`;
 const [copyFailed,setCopyFailed]=useState(false);
 /* نسخٌ يمنعه المتصفح كان يمرّ بلا أثر: زرٌّ يُضغط فلا شيء يحدث ولا شيء يُقال. */
 const copy=async()=>{setCopyFailed(false);try{await navigator.clipboard.writeText(link);setCopied(true);window.setTimeout(()=>setCopied(false),1800)}catch{setCopyFailed(true)}};
 /* الرابط كان يُنسخ ويُوزَّع دون أن يعرف أحد أن النسخة العامة لم تصل الخادم بعد: الصفحة
    تُعرض من ذاكرة جهاز الإدارة، ثم يردّ الخادم «لم نعثر على المسابقة» بعد ملء النموذج
    كاملًا. الحالة الآن تُفحص هنا، قبل أن يُرسَل الرابط لأحد، ومعها إصلاحٌ بضغطة واحدة. */
 const {checkPublicCompetitionPublished,republishPublicCompetition}=useAppStore();
 const [pub,setPub]=useState<'checking'|'published'|'missing'|'unknown'>('checking');
 const [pubNote,setPubNote]=useState('');
 const [publishing,setPublishing]=useState(false);
 const refreshPub=useCallback(()=>{setPub('checking');setPubNote('');void checkPublicCompetitionPublished().then(out=>{setPub(out.state);setPubNote(out.reason)})},[checkPublicCompetitionPublished]);
 useEffect(()=>{refreshPub()},[c.id,refreshPub]);
 const republish=async()=>{setPublishing(true);setPubNote('');const out=await republishPublicCompetition();setPublishing(false);if(out.ok){setPub('published')}else{setPubNote(out.reason);setPub('missing')}};
 /* ثلاث حالات تُقال كما هي: منشور، وغير منشور، ولا نعلم. والثالثة لا تُلبس ثوب الثانية. */
 const pubTone=pub==='published'?'ok':pub==='missing'?'warn':'quiet';
 const pubLine=pub==='checking'?(ar?'نفحص حالة النشر…':'Checking publication…')
  :pub==='published'?(ar?'الرابط منشور ويعمل للجميع':'Published and working for everyone')
  :pub==='missing'?(ar?'الرابط غير منشور بعد على الخادم':'Not published to the server yet')
  :(ar?'تعذّر التأكّد من حالة النشر الآن':'Publication status could not be confirmed right now');
 return <div className="mizan-surface p-5"><div className="mizan-kicker">{ar?'مشاركة التسجيل':'SHARE REGISTRATION'}</div><h2 className="font-extrabold mt-1">{ar?'رابط تسجيل هذه المسابقة':'This competition’s registration link'}</h2>
  <div className={`mt-3 rounded-2xl border p-3.5 ${pubTone==='warn'?'border-[#E2D6BE] bg-[#F3EFE6]':'border-[#dcdad2] bg-[#f8f7f2]'}`}><div className="flex flex-wrap items-center gap-2.5">
   <span className={`w-2.5 h-2.5 rounded-full ${pubTone==='ok'?'bg-[#2F6555]':pubTone==='warn'?'bg-[#9B7542]':'bg-[#b9b6ad]'}`}/>
   <span className="text-xs font-black text-[#3f4742]">{pubLine}</span>
   {pub!=='published'&&pub!=='checking'&&<Button size="sm" variant="secondary" onClick={()=>void republish()} disabled={publishing}>{publishing?(ar?'جارٍ النشر…':'Publishing…'):(ar?'انشر الآن':'Publish now')}</Button>}
   {pub!=='checking'&&pub!=='missing'&&<button type="button" onClick={refreshPub} className="text-[11px] font-bold text-[#214C40] underline">{ar?'أعد الفحص':'Re-check'}</button>}
  </div>
  {pub==='unknown'&&!!pubNote&&<p className="text-[11px] font-bold text-[#5f6763] mt-2 leading-6">{pubNote}</p>}
  {pub==='missing'&&!!pubNote&&<p role="alert" className="text-[11px] font-bold text-[#874b43] mt-2 leading-6">{pubNote}</p>}
  </div>
  <div className="mt-4 grid sm:grid-cols-[1fr_auto] gap-4 items-center"><div className="min-w-0"><div dir="ltr" className="rounded-xl border border-[#dcdad2] bg-white px-3 py-2.5 text-xs font-mono truncate">{link}</div><div className="flex gap-2 mt-3"><Button size="sm" icon={<Copy className="w-4 h-4"/>} onClick={()=>void copy()}>{copied?(ar?'تم النسخ':'Copied'):(ar?'نسخ':'Copy')}</Button><a href={link} title={ar?'فتح رابط التسجيل':'Open registration link'} aria-label={ar?'فتح رابط التسجيل':'Open registration link'} className="w-10 h-10 inline-grid place-items-center rounded-xl border border-[#dcdad2] text-[#214C40] hover:bg-[#f3f1eb]"><Share2 className="w-4 h-4"/></a></div>{copyFailed&&<p role="alert" className="text-[10px] font-bold text-[#874b43] mt-2">{ar?'المتصفح منع النسخ التلقائي. حدّد الرابط أعلاه وانسخه يدويًا.':'The browser blocked copying. Select the link above and copy it manually.'}</p>}<p className="text-[10px] text-[#696f6b] mt-3">{ar?'أرسل هذا الرابط للمتسابقين؛ يفتح نموذج تسجيل هذه المسابقة مباشرة.':'Send this link to participants; it opens this competition’s registration form directly.'}</p></div><div className="bg-white p-2 rounded-2xl border border-[#deddd6] justify-self-center"><RealQRCode value={link} size={120}/></div></div></div>;
};

const OperationsPolicySection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'سياسة التشغيل':'Operations policy'} subtitle={ar?'حدد إلى أي مدى تعمل المسابقة بلا موظفي استقبال أو توزيع يدوي.':'Choose how far the competition can run without reception or manual routing.'}/><div className="grid xl:grid-cols-2 gap-3 items-start [&>*]:min-w-0"><div className="rounded-2xl border border-[#e2e0d8] bg-[#fbfaf7] overflow-hidden"><div className="px-4 pt-3 pb-2 border-b border-[#eae8e0]"><div className="text-[11px] font-black text-[#48514c]">{ar?'الاستقبال والحضور':'Reception & arrival'}</div><p className="text-[10px] leading-5 text-[#656b66] mt-0.5">{ar?'كيف يصل المتسابق إلى مقعده دون طابور يدوي.':'How a participant reaches their seat without a manual queue.'}</p></div><div className="mizan-surface-soft px-4"><Toggle value={policy.operations.selfCheckIn} onChange={v=>patch(p=>{p.operations.selfCheckIn=v})} label={ar?'حضور ذاتي من الهاتف':'Mobile self check-in'}/><Toggle value={policy.operations.kioskCheckIn} onChange={v=>patch(p=>{p.operations.kioskCheckIn=v})} label={ar?'تسجيل ذاتي':'Self-service kiosk'}/><Toggle value={policy.operations.exceptionDesk} onChange={v=>patch(p=>{p.operations.exceptionDesk=v})} label={ar?'مكتب استثناء للحالات النادرة':'Exception desk'}/><Toggle value={policy.operations.smartArrivalSlots} onChange={v=>patch(p=>{p.operations.smartArrivalSlots=v})} label={ar?'مواعيد حضور ذكية':'Smart arrival slots'}/></div></div><div className="rounded-2xl border border-[#e2e0d8] bg-[#fbfaf7] overflow-hidden"><div className="px-4 pt-3 pb-2 border-b border-[#eae8e0]"><div className="text-[11px] font-black text-[#48514c]">{ar?'القاعة والاستمرارية':'Hall & continuity'}</div><p className="text-[10px] leading-5 text-[#656b66] mt-0.5">{ar?'ما يحكم شاشات القاعة والتوزيع وبقاء العمل عند انقطاع الشبكة.':'What governs hall screens, routing and staying operational offline.'}</p></div><div className="mizan-surface-soft px-4"><Toggle value={policy.operations.autoRouting} onChange={v=>patch(p=>{p.operations.autoRouting=v})} label={ar?'توزيع تلقائي على اللجان':'Automatic committee routing'}/><Toggle value={policy.operations.publicQueueUsesCodesOnly} onChange={v=>patch(p=>{p.operations.publicQueueUsesCodesOnly=v})} label={ar?'الشاشات العامة تستخدم الأكواد':'Public queue uses codes only'}/><Toggle value={policy.operations.offlineContinuity} onChange={v=>patch(p=>{p.operations.offlineContinuity=v})} label={ar?'استمرارية دون إنترنت':'Offline continuity'}/></div></div></div><div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'مهلة التأخر بالدقائق':'Late grace minutes'} value={policy.operations.lateArrivalGraceMinutes} onChange={v=>patch(p=>{p.operations.lateArrivalGraceMinutes=v})}/><Control label={ar?'البطاقة':'Badge'}><TinySelect value={policy.operations.badgeMode} onChange={v=>patch(p=>{p.operations.badgeMode=v as any})}><option value="digital">{ar?'رقمية':'Digital'}</option><option value="print">{ar?'مطبوعة':'Print'}</option><option value="both">{ar?'الاثنان':'Both'}</option><option value="none">{ar?'بدون':'None'}</option></TinySelect></Control></div><DistributionPolicyBlock ar={ar} policy={policy} patch={patch}/></div>;

/*
 * قرارات التوزيع.
 *
 * هذه الخمسة كان المحرّك يقرؤها ولا واجهةَ تكتبها: مجمَّدةً على الافتراضات، فبابُ
 * «قرارات تحتاج توقيع الجهة» لا يُوقَّع فيه شيء. وكلٌّ منها يمسّ عدل القاعة مباشرةً —
 * أين يجلس المتسابق، ومن يُقدَّم، وهل يُحكَّم في غير فئته — فبقاؤها بلا محرّرٍ يعني أن
 * الجهة تُحاسَب على قرارٍ لم تتّخذه.
 *
 * وكلّ ضابطٍ هنا يقول أثره بالعبارة، لا باسم الحقل: من يضبطه مسؤولُ مسابقة لا مبرمج.
 */
const DistributionPolicyBlock=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const ops=policy.operations;
 const cap=Math.round((ops.delegationShareCap??0.4)*100);
 return <div className="rounded-2xl border border-[#e2e0d8] bg-[#fbfaf7] overflow-hidden">
  <div className="px-4 pt-3 pb-2 border-b border-[#eae8e0]">
   <div className="text-[11px] font-black text-[#48514c]">{ar?'التوزيع على اللجان':'Routing to panels'}</div>
   <p className="text-[10px] leading-5 text-[#656b66] mt-0.5">{ar?'متى يُسنَد المتسابق، وبأيّ قيود عدالة، وماذا يحدث حين لا تؤهّله لجنة.':'When a participant is routed, under which fairness limits, and what happens when no panel qualifies.'}</p>
  </div>
  <div className="p-4 space-y-4">
   <Control label={ar?'متى تُسنَد اللجنة':'When the panel is assigned'}>
    <TinySelect value={ops.distributionMode??'ON_ARRIVAL'} onChange={v=>patch(p=>{p.operations.distributionMode=v as any})}>
     <option value="ON_ARRIVAL">{ar?'عند الوصول — البوابة تُسند كل واصل':'On arrival — the gate routes each person'}</option>
     <option value="BY_CATEGORY">{ar?'حسب الفئة — لكل فئةٍ لجنتها':'By category — each category has its panel'}</option>
     <option value="WAVES">{ar?'موجات — تُوزَّع الدفعة كلها مرة واحدة':'Waves — the whole batch is routed at once'}</option>
     <option value="PRE_ASSIGNED">{ar?'إسناد مسبق — اللجان تُحدَّد قبل اليوم':'Pre-assigned — panels are set before the day'}</option>
    </TinySelect>
    <span className="block text-[10px] text-[#656b66] mt-2 leading-5">{ar
     ?'«عند الوصول» أبسطها وأسرعها. و«حسب الفئة» تُقدّم اللجنة المكرَّسة لفئة المتسابق على المشتركة ولا تُسنده خارج فئته أبدًا — تُسنَد الفئات للجان من «التحكيم ← الفئات». و«الموجات» ترى التركيبة كلّها فتمنع وقوع وفدٍ كامل تحت لجنة واحدة، لكنها تحتاج من يضغط زر التوزيع. والرقم يُمنح عند الباب في الأنماط الأربعة.'
     :'“On arrival” is simplest. “By category” prefers the panel dedicated to the participant’s category over a shared one and never routes outside it — assign categories to panels under Judging → Categories. “Waves” sees the whole intake and stops one delegation filling a panel, but someone must run the distribution. The queue number is granted at the door in all four.'}</span>
   </Control>

   <Control label={ar?'حين لا تؤهّله أيُّ لجنة':'When no panel qualifies'}>
    <TinySelect value={ops.unmatchedArrivalPolicy??'INCIDENT'} onChange={v=>patch(p=>{p.operations.unmatchedArrivalPolicy=v as any})}>
     <option value="INCIDENT">{ar?'يدخل الطابور بلا إسناد وتُفتح حادثة':'Queue without a panel, and open an incident'}</option>
     <option value="ANY_AVAILABLE">{ar?'يُسنَد إلى أي لجنة متاحة':'Route to any available panel'}</option>
    </TinySelect>
    <span className="block text-[10px] text-[#656b66] mt-2 leading-5">{ar
     ?'«أي لجنة متاحة» لا يفحص الفئة، فيُكتشف الخطأ عند بدء الجلسة — وهو أسوأ موضع. والأول يُبقي رقمه ويُعلن الحاجة. وفي نمط «حسب الفئة» لا أثر لهذا الخيار: الإسناد خارج الفئة ممنوع فيه على كل حال.'
     :'“Any available” does not check the category, so the mistake surfaces when the session starts — the worst place. The first keeps the number and states the need. Under “By category” this setting has no effect: routing outside the category is refused there regardless.'}</span>
   </Control>

   <div className="mizan-surface-soft px-4 -mx-1">
    <Toggle value={ops.requireReadingQualifiedPanel===true} onChange={v=>patch(p=>{p.operations.requireReadingQualifiedPanel=v})} label={ar?'اشترط لجنة مؤهَّلة في الرواية':'Require a reading-qualified panel'}/>
   </div>
   <p className="text-[10px] text-[#656b66] -mt-2 leading-5">{ar
    ?'يمنع إسناد متسابقٍ إلى لجنةٍ لا يُجيز محكّموها روايته. يضيّق الخيارات وقد يُبقي بعضهم بلا لجنة، فلا يُفعَّل إلا حيث تُحكَّم روايات متعددة.'
    :'Stops routing someone to a panel whose judges are not certified in their reading. It narrows the options and can leave people unrouted, so enable it only where multiple readings are judged.'}</p>

   <div className="grid sm:grid-cols-2 gap-4">
    <NumberControl label={ar?'سقف حصة الوفد في اللجنة (٪)':'Delegation share cap per panel (%)'} value={cap} min={10} max={100} step={5} onChange={v=>patch(p=>{p.operations.delegationShareCap=Math.min(1,Math.max(0.1,v/100))})}/>
    <NumberControl label={ar?'أقصى عمق للطابور (٠ = بلا حد)':'Max queue depth (0 = no limit)'} value={ops.maxQueueDepth??0} min={0} max={200} onChange={v=>patch(p=>{p.operations.maxQueueDepth=v})}/>
   </div>
   <p className="text-[10px] text-[#656b66] -mt-1 leading-5">{ar
    ?`السقف يمنع وقوع وفدٍ كامل تحت لجنة واحدة؛ و${cap}٪ رقمٌ مقترح لا مُثبت، تضبطه الجهة. ولكل وفدٍ مقعدٌ واحد على الأقل مهما ضاق السقف. والعمق قيدٌ تفضيلي يُخفَّف قبل أن يبقى أحدٌ بلا لجنة.`
    :`The cap keeps one delegation from filling a panel; ${cap}% is a proposal, not a proven number — the organization sets it. Every delegation still gets at least one seat. Depth is a preference, relaxed before anyone is left unrouted.`}</p>
  </div>
 </div>;
};

const QuestionsSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const [questionsTab,setQuestionsTab]=useState<'draw'|'closing'>('draw');
 const questionsTabAnchor=useTabAnchor(questionsTab);
 const reveal=policy.questions.secureReveal||{requireParticipantPresence:true,judgeApprovalMode:'all_assigned' as const};
 const opening=policy.questions.openingPrompt||{mode:'approved_reference_audio' as const,autoplay:true,usageScope:'opening_prompt',preferredReciter:''};
 const cue=policy.questions.transitionCue||{enabled:true,phraseArabic:'',phraseEnglish:'',selectedPhraseIndexes:[0],autoAdvanceDelayMs:900};
 const phrases=ar?TRANSITION_PHRASES_AR:TRANSITION_PHRASES_EN;
 const legacyPhrase=ar?cue.phraseArabic:cue.phraseEnglish;
 const legacyIndex=legacyPhrase?phrases.indexOf(legacyPhrase):-1;
 const validSelected=(cue.selectedPhraseIndexes||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<phrases.length);
 const selected=[...new Set(validSelected.length?validSelected:[legacyIndex>=0?legacyIndex:0])];
 const setSelected=(next:number[])=>patch(p=>{const current=p.questions.transitionCue||{enabled:true,phraseArabic:'',phraseEnglish:'',autoAdvanceDelayMs:900};p.questions.transitionCue={...current,phraseArabic:'',phraseEnglish:'',audioUrl:undefined,selectedPhraseIndexes:[...new Set(next)].sort((a,b)=>a-b)}});
 const togglePhrase=(idx:number)=>{const next=selected.includes(idx)?selected.filter(x=>x!==idx):[...selected,idx];if(next.length)setSelected(next)};
 return <div className="space-y-5"><SectionTitle title={ar?'السحب العادل والأسئلة':'FairDraw & questions'} subtitle={ar?'حدد كيف يُختار السؤال، ومتى يُكشف، وكيف تبدأ التلاوة وتنتهي دون أن يرى المحكم السؤال مبكرًا.':'Define how a question is selected, revealed, opened and ended without early exposure.'}/>
  <div role="tablist" ref={questionsTabAnchor} aria-label={ar?'أقسام الأسئلة':'Question sections'} className="mizan-tabs">
   {([['draw',ar?'السحب والكشف':'Draw & reveal'],['closing',ar?'عبارات الإنهاء':'Closing phrases']] as const).map(([id,label])=><button key={id} type="button" role="tab" aria-selected={questionsTab===id} onClick={()=>setQuestionsTab(id)} className={`mizan-tab ${questionsTab===id?'is-active':''}`}>{label}</button>)}
  </div>
  {questionsTab==='draw'&&<div className="space-y-5">
  {/* السحب العادل يُثبت قابلية إعادة الإنتاج؛ هذا السطر يقيس ما لا يقيسه: تكافؤ الحِمل بين الأطقم. */}
  <FairDrawParityNote ar={ar}/>
  <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4"><Control label={ar?'طريقة السحب':'Draw mode'}><TinySelect value={policy.questions.drawMode} onChange={v=>patch(p=>{p.questions.drawMode=v as any})}><option value="fairdraw">{ar?'السحب العادل القابل للتحقق':'FairDraw'}</option><option value="pure_random">{ar?'عشوائي':'Pure random'}</option><option value="manual_approved">{ar?'معتمد يدوي':'Approved manual'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><NumberControl label={ar?'عدد الأسئلة':'Questions'} value={policy.questions.questionsPerParticipant} onChange={v=>patch(p=>{p.questions.questionsPerParticipant=Math.max(1,v)})}/><NumberControl label={ar?'الصعوبة المستهدفة':'Target difficulty'} step={0.1} min={1} max={5} value={policy.questions.targetDifficulty} onChange={v=>patch(p=>{p.questions.targetDifficulty=v})}/><NumberControl label={ar?'هامش الصعوبة':'Difficulty tolerance'} step={0.05} min={0} max={4} value={policy.questions.difficultyTolerance} onChange={v=>patch(p=>{p.questions.difficultyTolerance=Math.max(0,v)})}/></div>
  <details className="mizan-surface-soft px-4 py-1"><summary className="cursor-pointer select-none list-none py-3 flex items-center justify-between gap-2 text-xs font-black text-[#59615c]"><span>{ar?'إعدادات السحب المتقدمة — اختيارية':'Advanced draw settings — optional'}</span><span className="text-[10px] font-bold text-[#656b66]">{ar?'حسب سياسة المسابقة':'competition policy'}</span></summary><div className="pb-1"><div className="mb-3 rounded-xl border border-[#d9e4de] bg-[#F7FAF8] p-3 text-[11px] font-bold leading-5 text-[#214C40]">{ar?'يبدأ ميزان السحب العادل تلقائيًا عند بدء جلسة المتسابق؛ لا يحتاج المتسابق إلى زر سحب ولا يمكن تحويل هذه المسؤولية إليه.':'MIZAN starts FairDraw automatically when the participant session begins; there is no participant draw button and this responsibility cannot be delegated.'}</div><Toggle value={policy.questions.avoidRepeatWithinRound} onChange={v=>patch(p=>{p.questions.avoidRepeatWithinRound=v})} label={ar?'تجنب التكرار داخل الجولة':'Avoid repeats within round'}/><Toggle value={policy.questions.diversity.acrossJuz} onChange={v=>patch(p=>{p.questions.diversity.acrossJuz=v})} label={ar?'تنوع بين الأجزاء':'Across-Juz diversity'}/><Toggle value={policy.questions.diversity.acrossSurah} onChange={v=>patch(p=>{p.questions.diversity.acrossSurah=v})} label={ar?'تنوع بين السور':'Across-Surah diversity'}/><Toggle value={policy.questions.diversity.mutashabihatBalance} onChange={v=>patch(p=>{p.questions.diversity.mutashabihatBalance=v})} label={ar?'موازنة المتشابهات':'Mutashabihat balance'}/></div></details>
  <div className="grid lg:grid-cols-2 gap-3"><div className="mizan-surface p-4"><div className="mizan-kicker">{ar?'منع كشف السؤال مبكرًا':'SECURE REVEAL'}</div><div className="mt-3"><Toggle value={reveal.requireParticipantPresence} onChange={v=>patch(p=>{p.questions.secureReveal={...reveal,requireParticipantPresence:v}})} label={ar?'لا كشف قبل وجود المتسابق أمام اللجنة':'Require participant presence'}/></div><Control label={ar?'موافقة المحكمين':'Judge approval'}><TinySelect value={reveal.judgeApprovalMode} onChange={v=>patch(p=>{p.questions.secureReveal={...reveal,judgeApprovalMode:v as 'all_assigned'|'minimum'}})}><option value="all_assigned">{ar?'جميع المحكمين المكلّفين':'All assigned judges'}</option><option value="minimum">{ar?'حد أدنى محدد':'Configured minimum'}</option></TinySelect></Control>{reveal.judgeApprovalMode==='minimum'&&<div className="mt-3"><NumberControl label={ar?'الحد الأدنى للموافقات':'Minimum approvals'} value={reveal.minimumApprovals||1} onChange={v=>patch(p=>{p.questions.secureReveal={...reveal,minimumApprovals:Math.max(1,v)}})}/></div>}<p className="text-[10px] leading-5 text-[#656b66] mt-3">{ar?'الوضع الأعلى نزاهة هو موافقة كل المحكمين بعد حضور المتسابق.':'Highest-integrity mode requires every assigned judge after participant presence.'}</p></div><div className="mizan-surface p-4"><div className="mizan-kicker">{ar?'بداية التلاوة':'OPENING AYAH'}</div><div className="mt-3"><Toggle value={opening.autoplay} onChange={v=>patch(p=>{p.questions.openingPrompt={...opening,autoplay:v}})} label={ar?'تشغيل أول آية تلقائيًا بعد كشف السؤال':'Autoplay first ayah after reveal'}/></div><p className="text-[10px] leading-5 text-[#656b66] mt-3">{ar?'يُشغَّل أول آية للسؤال بصوت القارئ المعتمد المتفق عليه — لا يوجد تحويل آلي للنص القرآني إلى صوت.':'The question’s first ayah plays from the agreed approved reciter — Quran audio is never synthesized.'}</p></div></div>
    </div>}
  {questionsTab==='closing'&&<div className="space-y-5">
<div className="mizan-surface p-4 sm:p-5"><div className="flex flex-col sm:flex-row sm:items-start justify-between gap-3"><div><div className="mizan-kicker">{ar?'إنهاء الموضع':'PASSAGE END'}</div><h3 className="font-black mt-1">{ar?'عبارات إنهاء هادئة ومتنوعة':'Calm, varied stop cues'}</h3><p className="text-[10px] leading-5 text-[#656b66] mt-1 max-w-xl">{ar?'اختر عبارة واحدة أو عدة عبارات أو الكل. عند اختيار أكثر من واحدة يتناوب ميزان بينها تلقائيًا، ولا يوجد رفع تسجيل يدوي أو نص حر.':'Choose one, several, or all. MIZAN rotates selected cues automatically; there is no manual recording upload or free-text cue.'}</p></div><Toggle value={cue.enabled} onChange={v=>patch(p=>{p.questions.transitionCue={...cue,enabled:v}})} label={ar?'التنبيه الصوتي مفعّل':'Audio cue enabled'}/></div><div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={()=>setSelected(phrases.map((_,i)=>i))} className={`rounded-xl px-3 py-2 text-xs font-black border ${selected.length===phrases.length?'bg-[#214C40] text-white border-[#214C40]':'bg-white border-[#deddd6] text-[#214C40]'}`}>{ar?'اختيار الكل':'Select all'}</button><button type="button" onClick={()=>setSelected([selected[0]??0])} className="rounded-xl px-3 py-2 text-xs font-black border border-[#deddd6] bg-white text-[#59615c]">{ar?'واحدة فقط':'One only'}</button><span className="self-center text-[10px] text-[#656b66]">{ar?`${selected.length} مختارة`:`${selected.length} selected`}</span></div><div className="mt-3 grid md:grid-cols-2 gap-2">{phrases.map((phrase,idx)=>{const on=selected.includes(idx);return <button type="button" key={phrase} onClick={()=>togglePhrase(idx)} aria-pressed={on} className={`rounded-xl border px-3 py-3 text-start text-xs font-bold leading-5 transition ${on?'border-[#b7ccc2] bg-[#E7EEE9] text-[#214C40]':'border-[#e2e0d9] bg-[#fffefb] text-[#5e6661] hover:bg-[#f7f5ef]'}`}><span className="inline-flex w-5 h-5 me-2 rounded-full border items-center justify-center text-[10px] align-middle">{on?'✓':idx+1}</span>{phrase}</button>})}</div><div className="mt-4 max-w-sm"><NumberControl label={ar?'مهلة الانتقال بالمللي ثانية':'Transition delay (ms)'} value={cue.autoAdvanceDelayMs} onChange={v=>patch(p=>{p.questions.transitionCue={...cue,autoAdvanceDelayMs:Math.max(0,v)}})}/></div><p className="text-[10px] leading-5 text-[#656b66] mt-3">{ar?'يبدأ ميزان بالمقطع الصوتي المطابق المدمج، ثم يستخدم صوت الخادم لنفس العبارة غير القرآنية، ثم نطق الجهاز كحل أخير. لا يُرسل أي نص قرآني إلى تحويل النص إلى صوت.':'MIZAN first uses the matching built-in recording, then server speech for the same non-Quran cue, then device speech as a final fallback. Quran text is never sent to text-to-speech.'}</p></div>  </div>}

 </div>;
};

const JudgingSection=({store,ar,policy,patch}:{store:Store;ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const r=store.competition.ruleSet;
 const specialtyOptions=useMemo(()=>judgeSpecialtyOptions(r.criteria,ar),[r.criteria,ar]);
 const setCriteria=(criteria:typeof r.criteria)=>store.updateRuleSet({criteria});
 const patchCriterion=(i:number,next:Partial<(typeof r.criteria)[number]>)=>{const criteria=[...r.criteria];criteria[i]={...criteria[i],...next};setCriteria(criteria)};
 const addCriterion=()=>setCriteria([...r.criteria,{id:`criterion-${Date.now()}`,name:'',nameArabic:'معيار جديد',maxScore:10,weight:0,assignedJudgeType:'all'}]);
 const removeCriterion=(id:string)=>{if(r.criteria.length<=1)return;setCriteria(r.criteria.filter(c=>c.id!==id));patch(p=>{p.judging.actions.forEach(a=>{if(a.criterion===id){a.criterion='custom';a.enabled=false}})})};
 /* كانت السياسة كلها صفحة واحدة متراصة: معايير وأزرار ومفاتيح وإعدادات في عمود لا ينتهي.
    التقسيم إلى ثلاث تبويبات معنوي لا تجميلي: «المعايير» هي لائحة الدرجات، و«الإعداد» بنية
    اللجان والغرفة العمياء، و«النزاهة» مفاتيح السلوك التي تغيّر ما يمكن إثباته بعد المسابقة. */
 const [judgingTab,setJudgingTab]=useState<'rubric'|'actions'|'setup'|'conduct'>('rubric');
 const judgingTabAnchor=useTabAnchor(judgingTab);
 const judgingTabs=[
  {id:'rubric' as const,label:ar?'معايير الدرجة':'Score criteria'},
  {id:'actions' as const,label:ar?'أزرار المحكم':'Judge actions'},
  {id:'setup' as const,label:ar?'إعداد التحكيم':'Judging setup'},
  {id:'conduct' as const,label:ar?'النزاهة والسلوك':'Integrity & conduct'},
 ];
 const totalMax=r.criteria.reduce((s,c)=>s+(Number(c.maxScore)||0),0);
 return <div className="space-y-5">
  <SectionTitle title={ar?'سياسة التحكيم':'Judging policy'} subtitle={ar?'ابنِ معايير هذه المسابقة وأزرار محكميها كما تنص لائحتها؛ لا توجد معايير مفروضة من ميزان.':'Build this competition’s criteria and judge actions from its own rulebook; MIZAN imposes no scoring schema.'}/>
  <div role="tablist" ref={judgingTabAnchor} aria-label={ar?'أقسام سياسة التحكيم':'Judging policy sections'} className="mizan-tabs">
   {judgingTabs.map(t=><button key={t.id} type="button" role="tab" aria-selected={judgingTab===t.id} onClick={()=>setJudgingTab(t.id)} className={`mizan-tab ${judgingTab===t.id?'is-active':''}`}>{t.label}</button>)}
  </div>
  {judgingTab==='rubric'&&<div className="space-y-5">
   <div className="rounded-2xl border border-[#dfddd6] overflow-hidden">
    <div className="px-4 py-3 bg-[#f7f5ef] flex items-center justify-between gap-3">
     <div>
      <div className="text-xs font-black text-[#303733]">{ar?'معايير الدرجة':'Score criteria'}</div>
      <div className="text-[10px] text-[#656b66] mt-1">{ar?'اختصاص المحكم مشتق من هذه المعايير؛ إذا أضفت معيارًا جديدًا سيظهر كخيار للمحكمين تلقائيًا.':'Judge specialties come from these criteria; new criteria become judge specialty choices automatically.'}</div>
     </div>
     <div className="flex items-center gap-3 shrink-0">
      <span className="rounded-full bg-[#E7EEE9] px-2.5 py-1 text-[10px] font-black text-[#214C40]">{ar?`المجموع ${totalMax}`:`Total ${totalMax}`}</span>
      <button type="button" onClick={addCriterion} className="flex items-center gap-1 text-xs font-black text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'معيار':'Criterion'}</button>
     </div>
    </div>
    <div className="divide-y divide-[#e5e3dc]">
     {r.criteria.map((c,i)=><div key={c.id} className="p-3 sm:p-4">
      <div className="flex items-start gap-2">
       <div className="flex-1 grid sm:grid-cols-2 gap-2 [&>*]:min-w-0">
        <label className="block"><span className="mizan-field-label">{ar?'اسم المعيار (عربي)':'Criterion name (Arabic)'}</span><input value={c.nameArabic} onChange={e=>patchCriterion(i,{nameArabic:e.target.value})} className="mizan-input text-xs font-bold"/></label>
        <label className="block"><span className="mizan-field-label">{ar?'الاسم (إنجليزي)':'Name (English)'}</span><input value={c.name} onChange={e=>patchCriterion(i,{name:e.target.value})} className="mizan-input text-xs"/></label>
       </div>
       <button type="button" disabled={r.criteria.length<=1} onClick={()=>removeCriterion(c.id)} aria-label={ar?'حذف المعيار':'Remove criterion'} className="w-11 h-11 shrink-0 rounded-lg hover:bg-[#f2e8e5] disabled:opacity-25 text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button>
      </div>
      <div className="mt-2.5 grid grid-cols-2 sm:grid-cols-[104px_104px_minmax(0,1fr)] gap-2 [&>*]:min-w-0">
       <label className="block"><span className="mizan-field-label">{ar?'الدرجة القصوى':'Max score'}</span><input type="number" min="0" step=".25" value={c.maxScore} onChange={e=>patchCriterion(i,{maxScore:Math.max(0,Number(e.target.value))})} className="mizan-input text-xs"/></label>
       <label className="block"><span className="mizan-field-label">{ar?'الوزن (0–1)':'Weight (0–1)'}</span><input type="number" min="0" max="1" step=".05" value={c.weight} onChange={e=>patchCriterion(i,{weight:Math.max(0,Math.min(1,Number(e.target.value)))})} className="mizan-input text-xs"/></label>
       <label className="block col-span-2 sm:col-span-1"><span className="mizan-field-label">{ar?'اختصاص المحكم':'Judge specialty'}</span><select value={c.assignedJudgeType||'all'} onChange={e=>patchCriterion(i,{assignedJudgeType:e.target.value as any})} className="mizan-input text-xs"><option value="all">{ar?'كل المحكمين':'All judges'}</option>{specialtyOptions.filter(x=>x.id!=='all').map(x=><option key={x.id} value={x.id}>{x.label}</option>)}</select></label>
      </div>
     </div>)}
    </div>
   </div>
   <div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'الحد الأدنى للنجاح':'Minimum pass'} min={0} max={100} value={r.minimumPassingScore} onChange={v=>store.updateRuleSet({minimumPassingScore:v})}/><NumberControl label={ar?'مدة السؤال بالدقائق':'Question minutes'} value={r.questionDurationMinutes} onChange={v=>store.updateRuleSet({questionDurationMinutes:Math.max(1,v)})}/></div>
  </div>}
  {judgingTab==='actions'&&<div className="space-y-5">
   <div className="rounded-2xl border border-[#dfddd6] overflow-hidden">
    <div className="px-4 py-3 bg-[#f7f5ef] flex items-center justify-between gap-3">
     <div>
      <div className="text-xs font-black text-[#303733]">{ar?'أزرار المحكم':'Judge actions'}</div>
      <div className="text-[10px] text-[#656b66] mt-1">{ar?'اربط كل زر بمعيار من معاييرك، أو اجعله مخصصًا بلا خصم على معيار.':'Bind each action to one of your criteria, or keep it custom.'}</div>
     </div>
     <button type="button" onClick={()=>patch(p=>p.judging.actions.push({id:`custom-${Date.now()}`,eventType:`custom_${Date.now()}`,labelArabic:'إجراء',labelEnglish:'Action',shortArabic:'إجراء',shortEnglish:'Action',criterion:r.criteria[0]?.id||'custom',penalty:0,enabled:true,icon:'custom'}))} className="flex items-center gap-1 text-xs font-bold text-[#214C40] shrink-0"><Plus className="w-3.5 h-3.5"/>{ar?'إجراء':'Action'}</button>
    </div>
    <div className="divide-y divide-[#e5e3dc]">
     {policy.judging.actions.map((a,i)=><div key={a.id} className={`p-3 sm:p-4 ${a.enabled?'':'opacity-60'}`}>
      <div className="flex items-start gap-2">
       <label className="block flex-1 min-w-0"><span className="mizan-field-label">{ar?'اسم الزر':'Action label'}</span><input value={ar?a.labelArabic:a.labelEnglish} onChange={e=>patch(p=>{if(ar)p.judging.actions[i].labelArabic=e.target.value;else p.judging.actions[i].labelEnglish=e.target.value})} className="mizan-input text-sm font-bold"/></label>
       <div className="flex items-center gap-1.5 pt-5 shrink-0">
        <Chip active={a.enabled} onClick={()=>patch(p=>{p.judging.actions[i].enabled=!p.judging.actions[i].enabled})}>{a.enabled?(ar?'مفعّل':'On'):(ar?'متوقف':'Off')}</Chip>
        <button type="button" onClick={()=>patch(p=>{p.judging.actions=p.judging.actions.filter((_,x)=>x!==i)})} aria-label={ar?'حذف الإجراء':'Remove action'} className="w-11 h-11 rounded-lg hover:bg-[#f2e8e5] text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button>
       </div>
      </div>
      <div className="mt-2.5 grid grid-cols-[minmax(0,1fr)_104px] gap-2 [&>*]:min-w-0">
       <label className="block"><span className="mizan-field-label">{ar?'المعيار المرتبط':'Bound criterion'}</span><select value={a.criterion} onChange={e=>patch(p=>{p.judging.actions[i].criterion=e.target.value})} className="mizan-input text-xs">{r.criteria.map(c=><option key={c.id} value={c.id}>{bilingualName(c,ar)}</option>)}<option value="custom">{ar?'مخصص بلا معيار':'Custom / no criterion'}</option></select></label>
       <label className="block"><span className="mizan-field-label">{ar?'قيمة الخصم':'Penalty'}</span><input type="number" step=".25" min="0" value={a.penalty} onChange={e=>patch(p=>{p.judging.actions[i].penalty=Math.max(0,Number(e.target.value))})} className="mizan-input text-xs"/></label>
      </div>
     </div>)}
    </div>
   </div>
  </div>}
  {judgingTab==='setup'&&<div className="space-y-4">
   <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 [&>*]:min-w-0">
    <NumberControl label={ar?'عدد المحكمين':'Judges per panel'} min={1} max={15} value={r.judgesCountPerPanel} onChange={v=>store.updateRuleSet({judgesCountPerPanel:Math.max(1,Math.min(15,v))},{allowWhenFrozen:true})}/>
    {(()=>{const level=resolveBlindness(policy.judging).level;const info=BLIND_LEVELS.find(x=>x.id===level);return <div className="rounded-2xl border border-[#dfe5e1] bg-[#f8faf8] p-4"><Control label={ar?'الغرفة العمياء':'Blind chamber'}><TinySelect value={level} onChange={v=>patch(p=>{p.judging.blindnessLevel=v as any;p.judging.identityVisibility=v==='OFF'?'full':'code_only'})}>{BLIND_LEVELS.map(x=><option key={x.id} value={x.id}>{ar?x.labelArabic:x.labelEnglish}</option>)}</TinySelect></Control><p className="mt-2 text-[10px] leading-5 text-[#656b66]">{ar?info?.noteArabic:info?.noteEnglish}</p><p className="mt-1 text-[10px] leading-5 text-[#656b66]">{ar?'إخفاء الاسم وحده لا يكفي: الجنسية والجهة والرواية قنوات استدلال أيضًا. ويُسجَّل إثبات أن كل محكّم أقفل قبل كشف الهوية.':'Hiding the name alone is not enough: origin, affiliation and riwaya infer identity too. A proof records that every judge locked before identity was revealed.'}</p></div>})()}
   </div>
   <details className="rounded-2xl border border-[#dfddd6] bg-[#fbfaf7] p-4">
    <summary className="cursor-pointer select-none text-xs font-black text-[#48514c]">{ar?'إعدادات تحكيم متقدمة':'Advanced judging settings'}</summary>
    <p className="mt-2 text-[10px] leading-5 text-[#696f6b]">{ar?'لا تحتاج لتغييرها في معظم المسابقات. تظهر هنا فقط لأنها تغيّر طريقة عمل التحكيم فعليًا.':'Most competitions do not need to change these settings. They are shown here only because they alter judging behavior.'}</p>
    <div className="mt-4 grid grid-cols-1 xl:grid-cols-2 gap-4">
     <Control label={ar?'طريقة توزيع التقييم':'How judging work is distributed'}><TinySelect value={policy.judging.mode} onChange={v=>patch(p=>{p.judging.mode=v as any})}><option value="all_judges_all_criteria">{ar?'كل المحكمين يقيّمون جميع المعايير':'Every judge scores all criteria'}</option><option value="specialized_judges">{ar?'كل محكم يقيّم تخصصاته':'Each judge scores selected specialties'}</option><option value="hybrid">{ar?'توزيع مختلط حسب اللجنة':'Mixed distribution by panel'}</option></TinySelect></Control>
     <Control label={ar?'أسلوب تسجيل التحكيم':'How judges record evaluation'}><TinySelect value={policy.judging.scoreEntryMode} onChange={v=>patch(p=>{p.judging.scoreEntryMode=v as any})}><option value="event_based">{ar?'تسجيل الملاحظات والأخطاء أثناء التلاوة':'Record marks during recitation'}</option><option value="direct_score">{ar?'إدخال درجة نهائية مباشرة':'Enter a final score directly'}</option><option value="hybrid">{ar?'استخدام الطريقتين':'Use both methods'}</option></TinySelect></Control>
    </div>
   </details>
  </div>}
  {judgingTab==='conduct'&&<div className="space-y-3">
   <div className="rounded-2xl border border-[#e2e0d8] bg-[#fbfaf7] overflow-hidden">
    <div className="px-4 pt-3 pb-2 border-b border-[#eae8e0]"><div className="text-[11px] font-black text-[#48514c]">{ar?'نزاهة التحكيم':'Judging integrity'}</div><p className="text-[10px] leading-5 text-[#656b66] mt-0.5">{ar?'ما يحمي استقلال الحكم ودليله. تغييرها يغيّر ما يمكن إثباته بعد المسابقة.':'What protects the independence of a judgement and the evidence behind it.'}</p></div>
    <div className="mizan-surface-soft px-4"><Toggle value={policy.judging.independentUntilLock} onChange={v=>patch(p=>{p.judging.independentUntilLock=v})} label={ar?'مستقل حتى القفل':'Independent until lock'}/><Toggle value={policy.judging.requireAudioRecording} onChange={v=>patch(p=>{p.judging.requireAudioRecording=v})} label={ar?'تسجيل الصوت مطلوب':'Audio recording required'}/><Toggle value={policy.judging.calibrationRequired} onChange={v=>patch(p=>{p.judging.calibrationRequired=v})} label={ar?'معايرة المحكمين':'Judge calibration'}/><Toggle value={r.dropExtremes} onChange={v=>store.updateRuleSet({dropExtremes:v})} label={ar?'إسقاط أعلى وأدنى درجة':'Drop highest and lowest'}/></div>
   </div>
   <div className="rounded-2xl border border-[#e2e0d8] bg-[#fbfaf7] overflow-hidden">
    <div className="px-4 pt-3 pb-2 border-b border-[#eae8e0]"><div className="text-[11px] font-black text-[#48514c]">{ar?'أدوات المحكم أثناء الجلسة':'Judge tools during a session'}</div><p className="text-[10px] leading-5 text-[#656b66] mt-0.5">{ar?'ما يراه المحكّم ويستطيع فعله وهو أمام المتسابق.':'What the judge sees and can do while the participant is in front of them.'}</p></div>
    <div className="mizan-surface-soft px-4"><Toggle value={policy.judging.allowPhysicalJudgePad} onChange={v=>patch(p=>{p.judging.allowPhysicalJudgePad=v})} label={ar?'لوحة المحكم والاختصارات':'Judge Pad / shortcuts'}/><Toggle value={policy.judging.showRunningScoreToJudge!==false} onChange={v=>patch(p=>{p.judging.showRunningScoreToJudge=v})} label={ar?'إظهار مجموع الخصم للمحكم أثناء التلاوة':'Show running deduction total to judge'}/><Toggle value={policy.judging.allowJudgeUndo!==false} onChange={v=>patch(p=>{p.judging.allowJudgeUndo=v})} label={ar?'السماح للمحكم بالتراجع عن آخر ملاحظة':'Allow judge to undo last mark'}/></div>
   </div>
   <div className="rounded-2xl border border-[#e2e0d8] bg-[#fbfaf7] overflow-hidden">
    <div className="px-4 pt-3 pb-2 border-b border-[#eae8e0]"><div className="text-[11px] font-black text-[#48514c]">{ar?'المساندة والاحتياط':'Assistance and reserve'}</div><p className="text-[10px] leading-5 text-[#656b66] mt-0.5">{ar?'إمكانات تعمل خلف التحكيم ولا تخصم درجة.':'Capabilities that run behind judging and never deduct a score.'}</p></div>
    <div className="mizan-surface-soft px-4"><Toggle value={policy.judging.silentAiGuardian} onChange={v=>patch(p=>{p.judging.silentAiGuardian=v})} label={ar?'الذكاء الاصطناعي صامت للمراجعة فقط':'Silent AI review only'}/><Toggle value={policy.judging.reserveJudgeAllowed} onChange={v=>patch(p=>{p.judging.reserveJudgeAllowed=v})} label={ar?'محكم احتياط':'Reserve judge'}/></div>
   </div>
   <AdvisoryNote>{ar?'الذكاء الاصطناعي لا يخصم أي درجة. أي إشارة آلية تتحول إلى مراجعة بشرية بعد أن يقفل المحكم تقييمه.':'AI never deducts a score. Any machine observation becomes a human review suggestion only after judges lock.'}</AdvisoryNote>
  </div>}
 </div>;
};

const AppealsSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'سياسة الاعتراض':'Appeals policy'} subtitle={ar?'كل مسابقة تقرر هل يوجد اعتراض، مدته، أسبابه، ومن يراجعه.':'Each competition decides whether appeals exist, their window, grounds and reviewer.'}/><div className="mizan-surface-soft px-4"><Toggle value={policy.appeals.enabled} onChange={v=>patch(p=>{p.appeals.enabled=v})} label={ar?'الاعتراضات مفعلة':'Appeals enabled'}/><Toggle value={policy.appeals.allowScoreChange} onChange={v=>patch(p=>{p.appeals.allowScoreChange=v})} label={ar?'يمكن أن ينتج تعديل درجة بعد قرار بشري':'Human appeal decision may change score'}/></div>{policy.appeals.enabled&&<div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'النافذة بالساعات':'Window hours'} value={policy.appeals.windowHours} onChange={v=>patch(p=>{p.appeals.windowHours=Math.max(1,v)})}/><Control label={ar?'المراجع':'Reviewer'}><TinySelect value={policy.appeals.reviewerRole} onChange={v=>patch(p=>{p.appeals.reviewerRole=v as any})}><option value="head_judge">{ar?'رئيس التحكيم':'Head Judge'}</option><option value="committee">{ar?'اللجنة':'Committee'}</option></TinySelect></Control></div>}<div><div className="text-xs font-black text-[#606662] mb-2">{ar?'الأسباب المسموحة':'Allowed grounds'}</div><div className="flex flex-wrap gap-2">{policy.appeals.grounds.map(g=><Badge key={g} variant="neutral" dot={false}>{uiToken(g,ar)}</Badge>)}</div></div></div>;

const ResultPolicySection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'النتائج والاعتماد':'Results & sealing'} subtitle={ar?'النتيجة قد تكون فورية أو خاصة أو مؤجلة للحفل حسب سياسة المسابقة.':'Visibility can be immediate, private, delayed or ceremony-only.'}/><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'الإظهار':'Visibility'}><TinySelect value={policy.results.visibility} onChange={v=>patch(p=>{p.results.visibility=v as any})}><option value="immediate">{ar?'فوري':'Immediate'}</option><option value="after_committee">{ar?'بعد اللجنة':'After committee'}</option><option value="after_round">{ar?'بعد الجولة':'After round'}</option><option value="ceremony_only">{ar?'الحفل فقط':'Ceremony only'}</option><option value="private_only">{ar?'خاص':'Private only'}</option></TinySelect></Control><Control label={ar?'الترتيب العام':'Leaderboard'}><TinySelect value={policy.results.publicLeaderboard} onChange={v=>patch(p=>{p.results.publicLeaderboard=v as any})}><option value="disabled">{ar?'متوقف':'Disabled'}</option><option value="top_only">{ar?'الأوائل فقط':'Top only'}</option><option value="full">{ar?'كامل':'Full'}</option></TinySelect></Control><Control label={ar?'التأهل':'Qualification'}><TinySelect value={policy.results.qualificationRule} onChange={v=>patch(p=>{p.results.qualificationRule=v as any})}><option value="top_n">{ar?'أعلى عدد محدد':'Top N'}</option><option value="minimum_score">{ar?'حد أدنى':'Minimum score'}</option><option value="custom">{ar?'مخصص':'Custom'}</option></TinySelect></Control><NumberControl label={ar?'قيمة التأهل':'Qualification value'} value={policy.results.qualificationValue} onChange={v=>patch(p=>{p.results.qualificationValue=v})}/></div><div className="mizan-surface-soft px-4"><Toggle value={policy.results.requireDualApprovalToSeal} onChange={v=>patch(p=>{p.results.requireDualApprovalToSeal=v})} label={ar?'اعتمادان مستقلان قبل الختم':'Two independent approvals before seal'}/></div><div><div className="text-xs font-black text-[#606662] mb-2">{ar?'قواعد كسر التعادل':'Tie-break order'}</div><div className="flex flex-wrap gap-2">{policy.results.tieBreakRules.map((x,i)=><Badge key={`${x}-${i}`} variant="neutral" dot={false}>{i+1}. {uiToken(x,ar)}</Badge>)}</div></div></div>;

const CertificateSection=({store,ar,policy,patch}:{store:Store;ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const cp=policy.certificates;const brand=store.organization.brand;const title=ar?(cp.titleArabic||'شهادة'):(cp.titleEnglish||'Certificate');const award=ar?(cp.awardTextArabic||''):(cp.awardTextEnglish||'');const orgName=ar?(brand.displayNameArabic||brand.nameArabic):(brand.displayName||brand.name);const competitionName=bilingualName(store.competition,ar);const verifyLink=`${typeof window!=='undefined'?window.location.origin:''}/#verify`;
 return <div className="space-y-5"><SectionTitle title={ar?'الشهادة':'Certificate'} subtitle={ar?'صمّم محتوى شهادة هادئة ورسمية، ثم يضيف ميزان التحقق الرقمي من دون أكواد تقنية مشوشة.':'Compose a calm official certificate; MIZAN adds digital verification without exposing technical noise.'}/><div className="grid xl:grid-cols-[1fr_.85fr] gap-5 items-start"><div className="space-y-4"><div className="mizan-surface-soft px-4"><Toggle value={cp.enabled} onChange={v=>patch(p=>{p.certificates.enabled=v})} label={ar?'الشهادات مفعلة':'Certificates enabled'}/><Toggle value={cp.autoIssue} onChange={v=>patch(p=>{p.certificates.autoIssue=v})} label={ar?'إصدار تلقائي بعد الإغلاق':'Auto issue after finalization'}/><Toggle value={cp.publicVerification} onChange={v=>patch(p=>{p.certificates.publicVerification=v})} label={ar?'التحقق العام مفعّل':'Public verification enabled'}/><Toggle value={cp.showScore} onChange={v=>patch(p=>{p.certificates.showScore=v})} label={ar?'إظهار الدرجة':'Show score'}/><Toggle value={cp.showRank} onChange={v=>patch(p=>{p.certificates.showRank=v})} label={ar?'إظهار الترتيب':'Show rank'}/></div><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'من يستلم':'Issue for'}><TinySelect value={cp.issueFor} onChange={v=>patch(p=>{p.certificates.issueFor=v as any})}><option value="all_participants">{ar?'كل المشاركين':'All participants'}</option><option value="qualified">{ar?'المتأهلون':'Qualified'}</option><option value="winners">{ar?'الفائزون':'Winners'}</option><option value="custom">{ar?'حسب قاعدة المسابقة':'Competition rule'}</option></TinySelect></Control><TextControl label={ar?'عنوان الشهادة':'Certificate title'} value={title} onChange={v=>patch(p=>{if(ar)p.certificates.titleArabic=v;else p.certificates.titleEnglish=v})}/></div><Control label={ar?'نص الاستحقاق':'Award text'}><textarea value={award} onChange={e=>patch(p=>{if(ar)p.certificates.awardTextArabic=e.target.value;else p.certificates.awardTextEnglish=e.target.value})} className="mizan-textarea min-h-28 text-sm resize-none"/></Control><div><div className="flex items-center justify-between"><div><div className="text-xs font-black text-[#606662]">{ar?'التوقيعات':'Signatories'}</div><div className="text-[10px] text-[#656b66] mt-1">{ar?'تظهر كمساحات توقيع نظيفة في أسفل الشهادة.':'Rendered as clean signature blocks at the certificate foot.'}</div></div><button type="button" onClick={()=>patch(p=>{p.certificates.signatories=[...(p.certificates.signatories||[]),{name:'',title:''}]})} className="flex items-center gap-1 text-xs font-bold text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'موقّع':'Signatory'}</button></div><div className="divide-y divide-[#e5e3dc] mt-2">{(cp.signatories||[]).map((s,i)=><div key={i} className="py-3 grid grid-cols-[1fr_1fr_auto] gap-2"><input placeholder={ar?'الاسم':'Name'} value={s.name} onChange={e=>patch(p=>{p.certificates.signatories![i].name=e.target.value})} className="mizan-input text-sm"/><input placeholder={ar?'الصفة':'Title'} value={s.title} onChange={e=>patch(p=>{p.certificates.signatories![i].title=e.target.value})} className="mizan-input text-sm"/><button type="button" onClick={()=>patch(p=>{p.certificates.signatories=p.certificates.signatories?.filter((_,x)=>x!==i)})} aria-label={ar?'حذف الموقّع':'Remove signatory'} className="w-11 h-11 rounded-lg hover:bg-[#f2e8e5] text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button></div>)}</div></div></div><aside className="sticky top-24"><div className="rounded-[26px] border border-[#d8cfbf] bg-[#fffdf8] p-5 sm:p-7 shadow-[0_16px_45px_rgba(66,54,35,.08)] text-center overflow-hidden relative"><div className="absolute inset-x-7 top-4 h-px bg-[#c9b58f]"/><div className="absolute inset-x-7 bottom-4 h-px bg-[#c9b58f]"/><div className="text-[9px] font-black tracking-[.22em] text-[#9B7542]">{ar?'وثيقة رسمية':'OFFICIAL DOCUMENT'}</div>{brand.logoUrl?<img src={brand.logoUrl} alt="" className="w-14 h-14 object-contain mx-auto mt-5"/>:<Award className="w-11 h-11 text-[#9B7542] mx-auto mt-5"/>}<div className="text-[11px] font-bold text-[#646965] mt-3">{orgName}</div><div className="text-[10px] text-[#656b66] mt-1">{competitionName}</div><h3 className="text-2xl font-black mt-6 text-[#202622]">{title}</h3><div className="mt-5 text-[10px] text-[#656b66]">{ar?'تُمنح إلى':'Presented to'}</div><div className="mt-1 text-xl font-black text-[#214C40]">{ar?'اسم المتسابق':'Participant Name'}</div><p className="mt-5 mx-auto max-w-md text-xs leading-6 text-[#4e5551]">{award||(ar?'يظهر هنا نص الاستحقاق الذي كتبته للمسابقة.':'Your award text appears here.')}</p>{(cp.showScore||cp.showRank)&&<div className="mt-5 flex justify-center gap-2">{cp.showScore&&<Badge variant="neutral" dot={false}>{ar?'الدرجة ٩٦٫٥':'Score 96.5'}</Badge>}{cp.showRank&&<Badge variant="emerald" dot={false}>{ar?'المركز الأول':'1st place'}</Badge>}</div>}<div className="mt-8 grid grid-cols-2 gap-5">{(cp.signatories||[]).slice(0,2).map((s,i)=><div key={i} className="border-t border-[#cfc8bb] pt-2 min-h-10"><div className="text-[10px] font-bold">{s.name||(ar?'اسم الموقّع':'Signatory')}</div><div className="text-[9px] text-[#656b66]">{s.title||(ar?'الصفة':'Title')}</div></div>)}</div>{cp.publicVerification&&<div className="mt-7 pt-4 border-t border-[#e3ded3] flex items-center justify-between gap-4 text-start"><div><div className="flex items-center gap-1 text-[10px] font-black text-[#214C40]"><ShieldCheck className="w-3.5 h-3.5"/>{ar?'قابلة للتحقق رقميًا':'Digitally verifiable'}</div><div className="text-[9px] text-[#656b66] mt-1">{ar?'امسح الرمز للتحقق من أصالة الشهادة':'Scan to verify certificate authenticity'}</div></div><div className="bg-white p-1.5 rounded-lg border border-[#e3ded3]"><RealQRCode value={verifyLink} size={54}/></div></div>}</div><div className="mt-2 text-center text-[9px] text-[#656b66]">{ar?'المعاينة تتحدث فورًا ولا تصدر شهادة حقيقية.':'Live preview only; no certificate is issued from this panel.'}</div></aside></div></div>;
};

const PrivacySection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'الخصوصية والاحتفاظ':'Privacy & retention'} subtitle={ar?'لا توجد سياسة احتفاظ واحدة لكل الجهات؛ هذه القيم تخص المسابقة الحالية.':'Retention is competition-specific and should match the organization’s legal policy.'}/><div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'الصوت — أيام':'Audio days'} value={policy.privacy.audioRetentionDays} onChange={v=>patch(p=>{p.privacy.audioRetentionDays=Math.max(0,v)})}/><NumberControl label={ar?'المستندات — أيام':'Document days'} value={policy.privacy.documentRetentionDays} onChange={v=>patch(p=>{p.privacy.documentRetentionDays=Math.max(0,v)})}/></div><div className="mizan-surface-soft px-4"><Toggle value={policy.privacy.allowAiProcessing} onChange={v=>patch(p=>{p.privacy.allowAiProcessing=v})} label={ar?'السماح بالمساندة الآلية':'Allow assistive AI processing'}/><Toggle value={policy.privacy.displayParticipantNameOnPublicScreens} onChange={v=>patch(p=>{p.privacy.displayParticipantNameOnPublicScreens=v})} label={ar?'إظهار الاسم على الشاشات العامة':'Show participant names publicly'}/><Toggle value={policy.privacy.allowAnonymousBenchmarking} onChange={v=>patch(p=>{p.privacy.allowAnonymousBenchmarking=v})} label={ar?'مقارنات مجهولة الهوية':'Anonymous benchmarking'}/></div></div>;

const ParticipantsView=({store,ar,query,setQuery,filtered}:{store:Store;ar:boolean;query:string;setQuery:(s:string)=>void;filtered:Store['participants']})=>{
 const {confirm,confirmDialog}=useConfirm(ar);
 const [pass,setPass]=useState<Store['participants'][number]|null>(null);
 const [passBusy,setPassBusy]=useState(false);const [passError,setPassError]=useState('');
 const [editP,setEditP]=useState<Store['participants'][number]|null>(null);
 const [ef,setEf]=useState({fullNameArabic:'',fullName:'',country:'',categoryId:''});
 const openEdit=(p:Store['participants'][number])=>{setEf({fullNameArabic:p.fullNameArabic||'',fullName:p.fullName||'',country:p.country||'',categoryId:p.categoryId||''});setEditP(p)};
 const saveEdit=()=>{if(!editP)return;store.updateParticipant(editP.id,{fullNameArabic:ef.fullNameArabic.trim(),fullName:ef.fullName.trim(),country:ef.country.trim(),categoryId:ef.categoryId});setEditP(null)};
 const deleteP=async(p:Store['participants'][number])=>{if(!(await confirm({
  title:ar?'حذف المتسابق؟':'Delete participant?',
  body:ar?`سيُحذف ${ar?p.fullNameArabic:p.fullName} (${p.code}) من هذه المسابقة. لا يمكن التراجع. ومن دخل لجنة أو له نتيجة لا يُحذف أصلًا؛ أوقفه بدل ذلك.`:`${p.fullName} (${p.code}) will be removed from this competition. This cannot be undone.`,
  confirmLabel:ar?'حذف':'Delete',tone:'destructive'})))return;const ok=store.removeParticipant(p.id);if(!ok)setPassError(ar?'لا يمكن حذف متسابق دخل لجنة أو له نتيجة. أوقفه بدل حذفه.':'Cannot delete a participant who entered a panel or has a result.')};
 const openPass=async(id:string)=>{setPassBusy(true);setPassError('');const p=await store.ensureParticipantJourneyAccess(id);if(p)setPass(p);else setPassError(ar?'تعذر نشر البطاقة؛ لم نعرض رمزًا غير صالح. تحقق من الاتصال وأعد المحاولة.':'The pass could not be published, so no dead QR was shown.');setPassBusy(false)};
 const origin=typeof window!=='undefined'?window.location.origin:'';
 const participantUrl=pass?.journeyAccessToken?`${origin}/#journey?comp=${store.competition.id}&key=${encodeURIComponent(pass.journeyAccessToken)}`:'';
 const guardianUrl=pass?.guardianAccessToken?`${origin}/#guardian?comp=${store.competition.id}&key=${encodeURIComponent(pass.guardianAccessToken)}`:'';
 const copy=(value:string)=>{if(value&&navigator.clipboard)void navigator.clipboard.writeText(value)};
 const exportJourneyCards=async()=>{setPassBusy(true);setPassError('');const batch=await store.prepareJourneyAccessBatch();if(!batch.participants.length){setPassError(ar?'لا توجد بطاقات صالحة للتصدير، أو تعذر نشرها.':'No valid journey passes could be exported.');setPassBusy(false);return}const q=(v:unknown)=>`"${String(v??'').replaceAll('"','""')}"`;/* الملف يُفتح في Excel أمام موظفين عرب: العناوين بلغتهم، ومعها BOM ليقرأ Excel العربية. */
 const rows=batch.participants.map(p=>[p.code,ar?p.fullNameArabic:p.fullName,p.email||'',p.phone||'',`${origin}/#journey?comp=${store.competition.id}&key=${encodeURIComponent(p.journeyAccessToken||'')}`,`${origin}/#guardian?comp=${store.competition.id}&key=${encodeURIComponent(p.guardianAccessToken||'')}`]);const csv=`\uFEFF${[ar?['كود المتسابق','اسم المتسابق','البريد الإلكتروني','رقم الهاتف','رابط المتسابق الخاص','رابط ولي الأمر الخاص']:['participant_code','participant_name','email','phone','participant_private_link','guardian_private_link'],...rows].map(row=>row.map(q).join(',')).join('\n')}`;const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=ar?`بطاقات-الرحلة-${store.competition.id}.csv`:`mizan-journey-cards-${store.competition.id}.csv`;a.click();URL.revokeObjectURL(url);if(batch.failed.length)setPassError(ar?`تم تصدير البطاقات المنشورة، وتعذر نشر ${batch.failed.length} بطاقة.`:`Published passes were exported; ${batch.failed.length} failed.`);setPassBusy(false)};
 return <div className="space-y-4">{confirmDialog}<div className="flex flex-wrap items-end justify-between gap-4"><div><div className="mizan-kicker">{ar?'المتسابقون':'PARTICIPANTS'}</div><h1 className="text-3xl font-black mt-1">{store.participants.length}</h1></div><div className="flex flex-wrap items-center gap-2"><Button size="sm" variant="outline" disabled={passBusy||!store.participants.length} onClick={()=>void exportJourneyCards()} icon={<FileUp className="w-4 h-4"/>}>{passBusy?(ar?'جارٍ تجهيز الروابط…':'Preparing…'):(ar?'تصدير بطاقات الرحلة':'Export journey passes')}</Button>{(()=>{const pend=store.participants.filter(p=>p.status==='submitted'||p.status==='under_review');return pend.length>0?<Button size="sm" variant="secondary" onClick={()=>{void (async()=>{if(!(await confirm({
  title:ar?'اعتماد كل الطلبات المعلّقة؟':'Approve all pending applications?',
  body:ar?`سيُعتمد ${pend.length} طلبًا دفعةً واحدة، ويُشعَر أصحابها. راجع الطلبات المشكوك فيها قبل الاعتماد الجماعي.`:`${pend.length} applications will be approved at once and their applicants notified.`,
  confirmLabel:ar?'اعتماد الكل':'Approve all'})))return;pend.forEach(p=>store.reviewParticipant(p.id,'approved'))})()}}>{ar?`اعتماد الكل (${pend.length})`:`Approve all (${pend.length})`}</Button>:null})()}<div className="relative w-full max-w-xs"><Search className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#686e6a]"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={ar?'اسم أو كود':'Name or code'} className="mizan-input mizan-input-icon-start text-sm"/></div></div></div>{passError&&<div role="status" className="rounded-xl bg-[#F5EDE2] px-4 py-3 text-xs font-bold text-[#725630]">{passError}</div>}
 <div className="mizan-surface overflow-hidden"><div className="divide-y divide-[#e5e3dc]">{filtered.length?filtered.map(p=>{const cat=store.competition.categories.find(c=>c.id===p.categoryId);const needs=p.status==='submitted'||p.status==='under_review';return <div key={p.id} className="p-4 sm:px-5 flex items-center gap-4"><div className="w-11 h-11 rounded-xl bg-[#E7EEE9] text-[#214C40] grid place-items-center font-black text-xs">{p.code.replace('A-','')}</div><div className="min-w-0 flex-1"><div className="font-bold text-sm truncate">{ar?p.fullNameArabic:p.fullName}</div><div className="text-[11px] text-[#656b66] mt-1 truncate">{ar?cat?.nameArabic:cat?.name} · {p.country||'—'}</div></div><Badge variant={p.status==='in_queue'?'amber':p.status==='tested'||p.status==='certified'?'emerald':'neutral'}>{statusLabel(p.status,ar)}</Badge>{needs?<div className="flex gap-1"><Button size="sm" variant="secondary" onClick={()=>store.reviewParticipant(p.id,'approved')}>{ar?'اعتماد':'Approve'}</Button><Button size="sm" variant="ghost" onClick={()=>store.reviewParticipant(p.id,'rejected')}>{ar?'رفض':'Reject'}</Button></div>:<button disabled={passBusy} onClick={()=>void openPass(p.id)} title={ar?'بطاقة رحلة المتسابق وولي الأمر':'Participant and guardian journey passes'} aria-label={ar?'فتح بطاقات الرحلة':'Open journey passes'} className="w-11 h-11 rounded-xl grid place-items-center text-[#214C40] hover:bg-[#edf2ef] disabled:opacity-40"><QrCode className="w-5 h-5"/></button>}<button onClick={()=>openEdit(p)} title={ar?'تعديل بيانات المتسابق':'Edit participant'} aria-label={ar?'تعديل بيانات المتسابق':'Edit participant'} className="w-11 h-11 rounded-xl grid place-items-center text-[#59615c] hover:bg-[#efede7]"><Pencil className="w-4 h-4"/></button><button onClick={()=>void deleteP(p)} title={ar?'حذف المتسابق':'Delete participant'} aria-label={ar?'حذف المتسابق':'Delete participant'} className="w-11 h-11 rounded-xl grid place-items-center text-[#94564d] hover:bg-[#f7ece9]"><Trash2 className="w-4 h-4"/></button></div>}):<div className="py-14 text-center text-sm text-[#656b66]">{ar?'لا يوجد متسابقون حقيقيون حتى الآن.':'No real participants yet.'}</div>}</div></div>
 <Modal isOpen={!!pass} onClose={()=>setPass(null)} title={ar?'بطاقات الرحلة':'Journey passes'} subtitle={ar?'دخول بلا حساب أو كلمة مرور. كل رابط خاص بصاحبه ويمكن إلغاؤه بإصدار رمز جديد.':'No account or password. Each pass is private to its holder.'} maxWidth="2xl"><div className="grid md:grid-cols-2 gap-4">{[{kind:'participant',title:ar?'المتسابق':'Participant',url:participantUrl,token:pass?.journeyAccessToken},{kind:'guardian',title:ar?'ولي الأمر':'Guardian',url:guardianUrl,token:pass?.guardianAccessToken}].map(x=><div key={x.kind} className="rounded-2xl border border-[#dedbd2] p-5 text-center"><div className="font-black mb-3">{x.title}</div>{x.url&&<div className="flex justify-center"><RealQRCode value={x.url} size={168} label={x.title}/></div>}<div className="mt-4 flex gap-2"><Button size="sm" variant="outline" onClick={()=>copy(x.url)} icon={<Copy className="w-4 h-4"/>}>{ar?'نسخ الرابط':'Copy link'}</Button><Button size="sm" variant="ghost" onClick={()=>copy(x.token||'')}>{ar?'نسخ الرمز':'Copy code'}</Button></div><p className="text-[10px] text-[#6a6f6b] mt-3 leading-5">{ar?'يُرسل للشخص المقصود فقط. الجهاز سيتذكره بعد أول دخول.':'Share only with the intended person; the device remembers it after first access.'}</p></div>)}</div></Modal>
 <Modal isOpen={!!editP} onClose={()=>setEditP(null)} title={ar?'تعديل بيانات المتسابق':'Edit participant'} subtitle={editP?.code}><div className="space-y-3"><label className="block"><span className="mizan-field-label">{ar?'الاسم بالعربية':'Arabic name'}</span><input className="mizan-input" lang="ar" data-mizan-kind="arabic" value={ef.fullNameArabic} onChange={e=>setEf({...ef,fullNameArabic:e.target.value})}/></label><label className="block"><span className="mizan-field-label">{ar?'الاسم بالإنجليزية':'English name'}</span><input className="mizan-input" lang="en" data-mizan-kind="latin" dir="ltr" value={ef.fullName} onChange={e=>setEf({...ef,fullName:e.target.value})}/></label><div className="grid sm:grid-cols-2 gap-3"><label className="block"><span className="mizan-field-label">{ar?'الدولة':'Country'}</span><input className="mizan-input" value={ef.country} onChange={e=>setEf({...ef,country:e.target.value})}/></label><label className="block"><span className="mizan-field-label">{ar?'الفئة':'Category'}</span><select className="mizan-input" value={ef.categoryId} onChange={e=>setEf({...ef,categoryId:e.target.value})}>{store.competition.categories.map(c=><option key={c.id} value={c.id}>{bilingualName(c,ar)}</option>)}</select></label></div><div className="flex justify-end gap-2 pt-1"><Button variant="ghost" onClick={()=>setEditP(null)}>{ar?'تراجع':'Cancel'}</Button><Button disabled={!ef.fullNameArabic.trim()&&!ef.fullName.trim()} onClick={saveEdit}>{ar?'حفظ':'Save'}</Button></div></div></Modal>
 </div>;
};

const ToolCard=({icon:Icon,title,description,disabled,onClick}:{icon:React.ComponentType<{className?:string}>;title:string;description:string;disabled?:boolean;onClick:()=>void})=><button type="button" disabled={disabled} onClick={onClick} className="mizan-surface p-4 text-start disabled:opacity-45 disabled:cursor-not-allowed hover:border-[#9ab0a8] transition"><Icon className="w-5 h-5 text-[#214C40]"/><div className="font-black text-sm mt-3">{title}</div><div className="text-[11px] text-[#666c68] mt-1 leading-5">{description}</div></button>;

const committeeAutoStatus=(c:Store['committees'][number],requiredJudges:number):'ready'|'testing'|'paused'|'offline'=>{if(c.status==='paused')return 'paused';if(c.devicesConnected<=0&&!c.audioInputOk)return 'offline';if(!c.audioInputOk||c.devicesConnected<=0||c.judgeIds.length<Math.max(1,requiredJudges)||!c.headJudgeId)return 'testing';return 'ready'};
const committeeStatusLabel=(status:'ready'|'testing'|'paused'|'offline',ar:boolean)=>status==='ready'?(ar?'جاهزة':'Ready'):status==='testing'?(ar?'جارٍ التحقق':'Checking'):status==='paused'?(ar?'متوقفة مؤقتًا':'Paused'):(ar?'غير متصلة':'Offline');
const fallbackSpecialtyLabel=(id:string,ar:boolean)=>({memorization:ar?'الحفظ':'Memorization',tajweed:ar?'التجويد':'Tajweed',performance:ar?'الأداء':'Performance',waqf_ibtida:ar?'الوقف والابتداء':'Waqf/Ibtida',all:ar?'شامل':'All criteria'} as Record<string,string>)[id]||id;
const judgeSpecialtyOptions=(criteria:{id:string;name:string;nameArabic:string;assignedJudgeType?:string}[],ar:boolean)=>[{id:'all',label:fallbackSpecialtyLabel('all',ar)},...Array.from(new Map(criteria.map(c=>[c.assignedJudgeType&&c.assignedJudgeType!=='all'?c.assignedJudgeType:c.id,{id:c.assignedJudgeType&&c.assignedJudgeType!=='all'?c.assignedJudgeType:c.id,label:ar?(c.nameArabic||fallbackSpecialtyLabel(c.id,true)):(c.name||fallbackSpecialtyLabel(c.id,false))}])).values()).filter(x=>x.id&&x.id!=='all')];

const OperationsView=({mode,store,ar,sim,simCount,setSimCount,attention}:{mode:'operations'|'judging';store:Store;ar:boolean;sim:any;simCount:number;setSimCount:(n:number)=>void;attention:any[]})=>{
 const {confirm,confirmDialog}=useConfirm(ar);
 const open=(surface:string)=>window.dispatchEvent(new CustomEvent('mizan:open-venue',{detail:surface}));
 const active=!['draft','configured','completed','archived'].includes(store.competition.status);
 const hasParticipants=store.participants.length>0, hasPanels=store.committees.length>0, hasResults=store.results.length>0;
 const [committeeMessage,setCommitteeMessage]=useState('');
 const [arrivalNote,setArrivalNote]=useState('');
 const specialtyOptions=useMemo(()=>judgeSpecialtyOptions(store.competition.ruleSet.criteria,ar),[store.competition.ruleSet.criteria,ar]);
 const toggleJudge=(committeeId:string,judgeId:string)=>{const c=store.committees.find(x=>x.id===committeeId);if(!c)return;const current=new Set(c.judgeIds);if(current.has(judgeId)){if(c.headJudgeId===judgeId){setCommitteeMessage(ar?'غيّر رئيس اللجنة أولًا قبل إزالة هذا المحكم.':'Change the panel chair before removing this judge.');return;}current.delete(judgeId);setCommitteeMessage('');}else{const judge=store.judges.find(j=>j.id===judgeId||j.userId===judgeId);const others=store.committees.filter(x=>x.id!==committeeId&&(x.judgeIds.includes(judgeId)||(judge&&x.judgeIds.includes(judge.userId))));if(others.length){const name=judge?(ar?judge.nameArabic:judge.name):'';const where=others.map(x=>ar?x.nameArabic:x.name).join('، ');setCommitteeMessage(ar?`تنبيه: ${name} مُسند أيضًا إلى (${where}). مسموح، لكن اختصاصاته في كل لجنة مستقلة.`:`Note: ${name} also sits on (${where}). Allowed — specialties are independent per panel.`);}else setCommitteeMessage('');current.add(judgeId);}store.updateCommittee(committeeId,{judgeIds:[...current]});};
 // Specialties are scoped to the panel, not the shared judge profile: the same judge can be
 // "شامل" on one committee and "تجويد" on another without the two panels overwriting each other.
 const toggleJudgeSpecialty=(committeeId:string,judgeId:string,specialty:string)=>store.updateCommitteeJudgeSpecialty(committeeId,judgeId,specialty);
 const committeeSpecs=(c:Store['committees'][number],j:Store['judges'][number]):Set<string>=>{const key=c.judgeIds.includes(j.id)?j.id:(c.judgeIds.includes(j.userId)?j.userId:j.id);const scoped=c.judgeSpecialties?.[key];const list=(scoped&&scoped.length)?scoped:(j.specialties?.length?j.specialties:[j.specialty||'all']);return new Set(list.filter(Boolean));};
 // A judge sitting on more than one panel is allowed (different panels, different scope) — we only warn.
 const judgeCommitteeCount=(j:Store['judges'][number])=>store.committees.filter(c=>c.judgeIds.includes(j.id)||c.judgeIds.includes(j.userId)).length;
 const headEligible=(j:Store['judges'][number])=>store.roleGrants.some(g=>g.id===j.identityGrantId&&g.role==='head_judge'&&g.status==='ACTIVE')||j.title==='رئيس لجنة';
 const toggleCategory=(committeeId:string,categoryId:string)=>{const c=store.committees.find(x=>x.id===committeeId);if(!c)return;const ids=new Set(c.assignedCategories);ids.has(categoryId)?ids.delete(categoryId):ids.add(categoryId);store.updateCommittee(committeeId,{assignedCategories:[...ids]});};
 const setHead=(committeeId:string,judgeId:string)=>{const c=store.committees.find(x=>x.id===committeeId);if(!c)return;const members=new Set(c.judgeIds);if(judgeId)members.add(judgeId);store.updateCommittee(committeeId,{headJudgeId:judgeId,judgeIds:[...members]});};
 const removePanel=async(committeeId:string)=>{if(!(await confirm({
  title:ar?'حذف اللجنة؟':'Delete panel?',
  body:ar?'اللجنة الفارغة تُحذف. وإن كان لها سجل تحكيم فلن يُحذف تاريخها: يحفظها النظام ويوقفها بدل ذلك.':'An empty panel is deleted. A panel with judging history is preserved and paused instead, so its record is never lost.',
  confirmLabel:ar?'حذف':'Delete',tone:'destructive'})))return;const out=store.removeCommittee(committeeId);setCommitteeMessage(out.ok?(ar?'تم حذف اللجنة الفارغة.':'Empty panel deleted.'):(out.mode==='paused_due_to_history'?(ar?'للجنة سجل تشغيلي؛ تم إيقافها مع حفظ التاريخ بدل حذفه.':'The panel has history, so it was preserved and paused.'):(ar?'تعذر العثور على اللجنة.':'Panel not found.')));};
 return <div className="space-y-5" data-operation-mode={mode}>{confirmDialog}{(store.continuityIncidents.some(x=>x.status!=='RESOLVED')||store.sessionRecoveries.some(x=>x.status==='PROPOSED'&&x.decision==='FULL_RETEST_LAST_RESORT'))&&<ContinuityRecovery/>}
 {/*
     ما يظهر في كل وضع صار قرار المكوّن لا قرار مُحدِّدٍ في ملف الأنماط يعدّ الأقسام بترتيبها.
     ذاك العدّ كان يخفي «القسم الأول» في وضع التحكيم، ثم انتقلت الأقسام غير المشتركة إلى شرطٍ
     في الشيفرة فصار قسم اللجان هو الأول — فاختفت شاشة التحكيم كلّها: عنوانٌ بلا لجان ولا زرّ
     إنشاء. القاعدة الآن: لا يُخفى ما يُعرض بالأنماط، ولا يُعرض إلا ما يُبنى.
   */}
 {mode==='operations'
  ? <div><div className="mizan-kicker">{ar?'إدارة يوم المسابقة':'EVENT DAY'}</div><h1 className="text-3xl font-black mt-1">{ar?'كل أداة في مكانها ووقتها':'Right tool, right moment'}</h1><p className="text-xs text-[#656b66] mt-2">{ar?'الأدوات التشغيلية لا تعمل قبل فتح المسابقة، ولا تعرض بيانات تجريبية عند غياب البيانات الحقيقية.':'Operational tools only run after opening, and never invent missing data.'}</p></div>
  : <div className="flex justify-end"><Button size="sm" variant="outline" onClick={()=>store.addCommittee()} disabled={['completed','archived'].includes(store.competition.status)} icon={<Plus className="w-4 h-4"/>}>{ar?'لجنة جديدة':'New panel'}</Button></div>}
 {(!active||!hasParticipants||!hasPanels)&&<div className="rounded-2xl border border-[#d8c7a7] bg-[#fffaf0] px-4 py-3"><div className="text-xs font-black text-[#604724]">{ar?'لماذا بعض الأدوات غير مفعّلة؟':'Why are some tools inactive?'}</div><ul className="mt-2 space-y-1 text-[10px] leading-5 text-[#6b5b45]">{!active&&<li>{ar?'• افتح المسابقة أولًا من «اليوم ← فتح المسابقة»؛ الأدوات التشغيلية لا تعمل قبل الفتح.':'• Open the competition first; operational tools stay off until then.'}</li>}{active&&!hasParticipants&&<li>{ar?'• لا يوجد متسابقون حقيقيون بعد — بوابة الحضور وشاشة الانتظار تحتاج متسابقين.':'• No real participants yet — check-in and waiting board need participants.'}</li>}{active&&!hasPanels&&<li>{ar?'• لا توجد لجان بعد — أنشئ لجنة لتفعيل خريطة القاعة ومختبر التحكيم.':'• No panels yet — create a panel to enable the hall map and judging lab.'}</li>}</ul></div>}
 {mode==='operations'&&<section><div className="text-xs font-black text-[#4f5752] mb-2">{ar?'الاستقبال والقاعة':'RECEPTION & HALL'}</div><div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3"><ToolCard icon={Fingerprint} title={ar?'بوابة الحضور':'Check-in gate'} description={ar?(active?'تسجيل حضور المتسابقين يوم الحدث.':'تتاح بعد فتح المسابقة.'):(active?'Check in real participants.':'Available after opening.')} disabled={!active||!hasParticipants} onClick={()=>open('kiosk')}/><ToolCard icon={MonitorX} title={ar?'شاشة الانتظار':'Waiting board'} description={ar?(hasParticipants?'شاشة القاعة للأكواد والأدوار الحقيقية فقط.':'تظهر بعد وجود متسابقين حقيقيين.'):(hasParticipants?'Real queue codes only.':'Needs real participants.')} disabled={!active||!hasParticipants} onClick={()=>open('waitingBoard')}/><ToolCard icon={MonitorDot} title={ar?'شاشة اللجنة':'Committee display'} description={ar?(hasPanels?'شاشة مستقلة للجنة واحدة: كودها الحالي وفئتها والتالون.':'تتاح بعد إنشاء لجنة حقيقية.'):(hasPanels?'One panel, its code and category.':'Needs a real panel.')} disabled={!active||!hasPanels} onClick={()=>open('committeeBoard')}/><ToolCard icon={MapPin} title={ar?'خريطة تلاوة القاعة':'Hall recitation map'} description={ar?(hasPanels?'تشغيل ومتابعة اللجان الموجودة فعليًا.':'تتاح بعد إنشاء لجنة حقيقية.'):(hasPanels?'Operate real panels.':'Needs a real panel.')} disabled={!active||!hasPanels} onClick={()=>open('hallMap')}/></div></section>}
 {/* «مختبر ذكاء التحكيم» و«البث والتغطية» لم يعودا بابين هنا. كل ما كان خلفهما انتقل إلى
     موضعه من العمل: تكافؤ القرعة في قسم السحب أعلاه، رادار المتشابهات عند رئيس التحكيم،
     نزاهة اللجان عند المدقق، شرح الوقف في استوديو تدرّب المتسابق، ومتابعة الكلمة على
     سطح المصحف الرسمي أمام المحكّم. */}
 {mode==='operations'&&<section><div className="text-xs font-black text-[#4f5752] mb-2">{ar?'الحفل والنتائج':'CEREMONY & RESULTS'}</div><div className="grid sm:grid-cols-2 gap-3"><ToolCard icon={Award} title={ar?'وضع الحفل':'Ceremony mode'} description={ar?(hasResults?'عرض النتائج المعتمدة في الحفل.':'يتاح بعد وجود نتائج حقيقية.'):(hasResults?'Show approved results.':'Needs real results.')} disabled={!active||!hasResults} onClick={()=>open('ceremony')}/><div className="mizan-surface p-4"><BadgeCheck className="w-5 h-5 text-[#214C40]"/><div className="font-black text-sm mt-3">{ar?'التحقق من الشهادات':'Certificate verification'}</div><div className="text-[11px] text-[#666c68] mt-1 leading-5">{ar?'خدمة عامة للجميع؛ مكانها الأساسي في الصفحة العامة للمسابقة، لا داخل صلاحيات الإدارة.':'Public for everyone; its primary home is the public competition page.'}</div><button onClick={()=>{window.location.hash='#verify'}} className="mt-3 text-xs font-black text-[#214C40] underline">{ar?'فتح الخدمة العامة':'Open public verifier'}</button></div></div></section>}
 <section className="mizan-surface p-5 sm:p-6"><div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4">{mode==='operations'?<div><div className="mizan-kicker">{ar?'توزيع لجان التحكيم':'JUDGING PANELS'}</div><h2 className="text-xl font-black mt-1">{ar?'من يرأس؟ من يحكّم؟ وأي فئات تصل إلى كل لجنة؟':'Chair, judges and category scope'}</h2><p className="text-xs text-[#656b66] mt-2 leading-6 max-w-3xl">{ar?'التوزيع هنا هو مصدر الحقيقة للتشغيل: رئيس اللجنة عضو في اللجنة تلقائيًا، وكل محكم يمكن أن يحمل أكثر من تخصص مأخوذ من معايير المسابقة نفسها.':'This is the operational source of truth for panel chair, members, category scope and each judge’s criterion specialties.'}</p></div>:<div/>}<div className="rounded-2xl bg-[#E7EEE9] px-4 py-3 text-[11px] font-bold text-[#214C40] shrink-0">{ar?`${store.committees.length} لجنة · ${store.judges.length} محكم`:`${store.committees.length} panels · ${store.judges.length} judges`}</div></div><CategoryCoverageNote store={store} ar={ar}/>{committeeMessage&&<div role="status" className="mt-4 rounded-xl bg-[#f3f1eb] px-4 py-3 text-xs font-bold text-[#515955]">{committeeMessage}</div>}<div className="grid md:grid-cols-2 2xl:grid-cols-3 gap-4 mt-5">{store.committees.map(c=><PanelCard key={c.id} c={c} store={store} ar={ar} specialtyOptions={specialtyOptions} toggleJudge={toggleJudge} toggleJudgeSpecialty={toggleJudgeSpecialty} committeeSpecs={committeeSpecs} judgeCommitteeCount={judgeCommitteeCount} headEligible={headEligible} toggleCategory={toggleCategory} setHead={setHead} removePanel={removePanel}/>)}{!store.committees.length&&<div className="md:col-span-2 2xl:col-span-3 rounded-2xl border border-dashed border-[#d9d6cd] p-8 text-center text-xs text-[#656b66]">{ar?'لا توجد لجان. أنشئ لجنة ثم عيّن رئيسها وأعضاءها وفئاتها من هنا.':'No panels yet.'}</div>}</div></section>
 {mode==='operations'&&store.committees.length>0&&<div className="grid xl:grid-cols-[1fr_.55fr] gap-4"><div className="mizan-surface p-5"><div className="flex items-center justify-between mb-5"><div><div className="mizan-kicker">{ar?'محاكاة السعة':'CAPACITY SIMULATION'}</div><h2 className="font-extrabold mt-1">{ar?'اختبر السعة على بياناتك الحالية':'Test capacity from current data'}</h2></div>{/* الزرّ كان يتوسّط ارتفاع حقلٍ فوقه تسمية، فيقف على سطرٍ لا يقف عليه جاره. الصفّ الآن
                   يستوي على قاعدةٍ واحدة، والزرّ بارتفاع الحقل نفسه — فيُقرأ العنصران سطرًا واحدًا. */}
                <div className="flex flex-wrap items-end gap-2"><label className="block"><span className="mizan-field-label">{ar?'عدد المحاكاة':'Runs'}</span><input type="number" min={1} max={40} value={simCount} onChange={e=>setSimCount(Number(e.target.value))} className="mizan-input w-20 text-center text-sm font-bold"/></label><Button size="sm" variant="outline" className="min-h-[var(--mizan-control-h)]" onClick={()=>{const out=store.optimizeArrivalSlots();setArrivalNote(ar?`وُزِّعت مواعيد الوصول على ${out.scheduled} متسابقًا — ${out.perWave} في كل موجة، ومتوسط الجلسة ${out.averageSessionMinutes} دقيقة. وصلهم الإشعار.`:`${out.scheduled} arrivals scheduled — ${out.perWave} per wave, ${out.averageSessionMinutes} min average. Participants notified.`)}}>{ar?'تحسين الوصول':'Optimize arrivals'}</Button></div></div><div className="grid grid-cols-3 gap-3"><MiniMetric value={sim.projectedFinishTime} label={ar?'انتهاء':'Finish'}/><MiniMetric value={`${sim.averageWaitMinutes}${ar?' د':'m'}`} label={ar?'انتظار':'Wait'}/><MiniMetric value={`${sim.maxWaitMinutes}${ar?' د':'m'}`} label={ar?'أقصى':'Max'}/></div><div className="mt-4 rounded-xl bg-[#E7EEE9] p-3 text-xs font-semibold text-[#214C40]">{ar?sim.optimizationAdviceArabic:sim.optimizationAdviceEnglish}</div>{arrivalNote&&<div role="status" className="mt-2 rounded-xl bg-[#f3f1eb] px-3 py-2.5 text-[11px] font-bold text-[#4f5752]">{arrivalNote}</div>}</div><div className="mizan-surface p-5"><div className="mizan-kicker">{ar?'الحالات الاستثنائية':'EXCEPTIONS'}</div><div className="mt-4 space-y-2">{attention.filter(x=>x.kind!=='setup').length?attention.filter(x=>x.kind!=='setup').map(x=><div key={x.id} className="flex items-start gap-2 text-xs font-semibold"><CircleAlert className="w-4 h-4 text-[#89673a] shrink-0"/>{x.title}</div>):<div className="text-center py-8 text-xs text-[#656b66]"><BadgeCheck className="w-6 h-6 text-[#2F6555] mx-auto mb-2"/>{ar?'لا توجد حالات':'No active exceptions'}</div>}</div></div></div>}
 </div>;
};

/*
 * تغطية الفئات.
 *
 * إسناد الفئة إلى لجنة قرارُ تشغيلٍ لا تفصيلُ عرض: فئةٌ بلا لجنة تعني أن كل من سجّل فيها
 * سيصل يوم المسابقة فيدخل الطابور بلا إسناد — ويُكتشف النقص عند الباب لا قبله بأسبوع.
 * ولجنةٌ بلا فئة لا يصلها أحد، فتقف فارغةً بينما غيرها يزدحم.
 *
 * فالسطر هنا يقول النقص بالاسم قبل اليوم، ويشتدّ حين يكون التوزيع «حسب الفئة» — إذ لا
 * لجنةَ احتياطية تلتقط من سقط: الفئة بلا لجنة تعني متسابقًا بلا لجنة، حتمًا.
 */
const CategoryCoverageNote=({store,ar}:{store:Store;ar:boolean})=>{
 const cats=store.competition.categories||[];
 if(!cats.length||!store.committees.length)return null;
 const byCategory=getCompetitionPolicy(store.competition).operations.distributionMode==='BY_CATEGORY';
 const uncovered=cats.filter(cat=>!store.committees.some(c=>c.status!=='offline'&&c.assignedCategories.includes(cat.id)));
 const emptyPanels=store.committees.filter(c=>!c.assignedCategories.length);
 if(!uncovered.length&&!emptyPanels.length)
  return <div className="mt-4 flex items-center gap-2 text-[11px] font-bold text-[#2F6555]"><Check className="w-3.5 h-3.5 shrink-0"/>{ar?'كل فئة لها لجنة تستقبلها، وكل لجنة لها فئة.':'Every category has a panel, and every panel has a category.'}</div>;
 return <div className="mt-4 rounded-2xl border border-[#E2D6BE] bg-[#F3EFE6] px-4 py-3">
  <div className="flex items-start gap-2.5">
   <AlertTriangle className="w-4 h-4 text-[#8b6837] shrink-0 mt-0.5"/>
   <div className="space-y-1.5 text-[11px] leading-6 text-[#6b5b45] font-bold">
    {!!uncovered.length&&<div>{ar?`لا لجنة تستقبل: ${uncovered.map(x=>x.nameArabic||x.name).join('، ')}.`:`No panel receives: ${uncovered.map(x=>x.name||x.nameArabic).join(', ')}.`}{byCategory?(ar?' والتوزيع «حسب الفئة»، فمن سجّل فيها يدخل الطابور بلا لجنة.':' Routing is by category, so anyone registered there queues unrouted.'):''}</div>}
    {!!emptyPanels.length&&<div>{ar?`لجان بلا فئة مُسندة: ${emptyPanels.map(x=>x.code).join('، ')} — لن يصلها أحد.`:`Panels with no category: ${emptyPanels.map(x=>x.code).join(', ')} — nobody will reach them.`}</div>}
    <div className="text-[10px] font-semibold">{ar?'الإسناد من تبويب «الفئات» داخل بطاقة اللجنة.':'Assign from the Categories tab inside each panel card.'}</div>
   </div>
  </div>
 </div>;
};

/* بطاقة اللجنة كانت تكدّس الأعضاء والفئات والمقاييس في عمود واحد طويل داخل شبكة عمودين.
   التبويب الداخلي «المحكمون / الفئات» يبقي هوية اللجنة ورئاستها ظاهرة دائمًا، ويجعل
   القوائم الكثيفة (قائمة كل محكمي الجهة ورقائق الاختصاصات) تظهر عند طلبها فقط. */
const PanelCard=({c,store,ar,specialtyOptions,toggleJudge,toggleJudgeSpecialty,committeeSpecs,judgeCommitteeCount,headEligible,toggleCategory,setHead,removePanel}:{c:Store['committees'][number];store:Store;ar:boolean;specialtyOptions:{id:string;label:string}[];toggleJudge:(committeeId:string,judgeId:string)=>void;toggleJudgeSpecialty:(committeeId:string,judgeId:string,specialty:string)=>void;committeeSpecs:(c:Store['committees'][number],j:Store['judges'][number])=>Set<string>;judgeCommitteeCount:(j:Store['judges'][number])=>number;headEligible:(j:Store['judges'][number])=>boolean;toggleCategory:(committeeId:string,categoryId:string)=>void;setHead:(committeeId:string,judgeId:string)=>void;removePanel:(committeeId:string)=>Promise<void>})=>{
 const auto=committeeAutoStatus(c,store.competition.ruleSet.judgesCountPerPanel);
 const assignedParticipants=store.participants.filter(p=>p.assignedCommitteeId===c.id).length;
 const eligibleParticipants=store.participants.filter(p=>c.assignedCategories.includes(p.categoryId)).length;
 const required=store.competition.ruleSet.judgesCountPerPanel;
 /* لجنةٌ بمحكّمٍ واحد لا رئيس فيها ولا مرؤوس: هو الحَكَم وهو الرئيس حكمًا. إظهار قائمة
    «رئيس اللجنة» هنا سؤالٌ بلا معنى، واشتراط صلاحية «رئيس تحكيم» عليه يعطّل لجنةً مكتملة.
    فتختفي القائمة، ويُثبَّت هو رئيسًا بلا طلبٍ من أحد. */
 const members=store.judges.filter(j=>c.judgeIds.includes(j.id)||c.judgeIds.includes(j.userId));
 const soloJudge=members.length===1?members[0]:undefined;
 useEffect(()=>{if(soloJudge&&c.headJudgeId!==soloJudge.id)setHead(c.id,soloJudge.id)},[soloJudge?.id,c.headJudgeId]);
 const [panelTab,setPanelTab]=useState<'judges'|'categories'>('judges');
 return <article className="rounded-3xl border border-[#e2e0d9] bg-[#fffefb] p-5 min-w-0 h-full flex flex-col">
  <div className="flex items-start justify-between gap-3">
   <div className="flex flex-wrap items-center gap-2"><Badge variant={auto==='offline'?'rose':auto==='testing'?'blue':auto==='paused'?'amber':'emerald'}>{c.code}</Badge><span className="text-[10px] font-black text-[#646965]">{ar?'حالة اللجنة — تلقائية':'Panel status — automatic'}</span><Badge variant="neutral">{committeeStatusLabel(auto,ar)}</Badge></div>
   <button type="button" onClick={()=>void removePanel(c.id)} className="w-11 h-11 rounded-xl border border-[#ead9d5] text-[#94564d] grid place-items-center hover:bg-[#f7ece9]" title={ar?'حذف اللجنة':'Delete panel'} aria-label={ar?'حذف اللجنة':'Delete panel'}><Trash2 className="w-4 h-4"/></button>
  </div>
  <input value={(ar?c.nameArabic:c.name)||''} onChange={e=>store.updateCommittee(c.id,ar?{nameArabic:e.target.value}:{name:e.target.value})} placeholder={ar?'اسم اللجنة':'Panel name'} aria-label={ar?'اسم اللجنة':'Panel name'} className="w-full bg-transparent border-0 p-0 font-black text-lg mt-3 outline-none"/>
  {/* «هذه اللجنة لفئة كذا» تُقرأ من وجه البطاقة لا من خلف تبويب: هي ما يحدّد من يصلها. */}
  <div className="mt-2 flex flex-wrap items-center gap-1.5">
   {c.assignedCategories.length
    ? c.assignedCategories.map(id=>{const cat=store.competition.categories.find(x=>x.id===id);return cat?<span key={id} className="rounded-full bg-[#E7EEE9] text-[#214C40] px-2.5 py-1 text-[10px] font-black">{ar?cat.nameArabic:cat.name}</span>:null})
    : <button type="button" onClick={()=>setPanelTab('categories')} className="rounded-full bg-[#F5EDE2] text-[#725630] px-2.5 py-1 text-[10px] font-black underline">{ar?'لم تُسند فئة — أسنِدها الآن':'No category — assign one'}</button>}
  </div>
  <div className={`grid gap-3 mt-4 ${soloJudge?'':'sm:grid-cols-2'}`}>
   {soloJudge?<div className="rounded-2xl border border-[#d7e1dc] bg-[#F7FAF8] px-4 py-3 flex items-center gap-2.5"><BadgeCheck className="w-4 h-4 text-[#2F6555] shrink-0"/><div className="min-w-0"><div className="text-xs font-black text-[#214C40] truncate">{ar?soloJudge.nameArabic:soloJudge.name}</div><div className="text-[10px] text-[#5d6b64] mt-0.5">{ar?'محكّم واحد في هذه اللجنة — فهو رئيسها حكمًا.':'A single judge on this panel — chair by default.'}</div></div></div>:
   <label className="block"><span className="text-[10px] font-black text-[#646965]">{ar?'رئيس اللجنة':'Panel chair'}</span><select value={c.headJudgeId||''} onChange={e=>setHead(c.id,e.target.value)} className="mizan-input mt-2"><option value="">{ar?'اختر رئيس اللجنة':'Choose chair'}</option>{store.judges.filter(j=>headEligible(j)||c.headJudgeId===j.id||c.headJudgeId===j.userId).map(j=><option key={j.id} value={j.id}>{ar?j.nameArabic:j.name}{headEligible(j)?'':(ar?' — بلا صلاحية رئاسة':' — no chair role')}</option>)}</select>{!store.judges.some(j=>headEligible(j))&&<p className="mt-1.5 text-[9px] leading-4 text-[#94724a]">{ar?'لا يوجد من يملك صلاحية «رئيس تحكيم». امنح الصلاحية من إدارة الدخول والصلاحيات.':'No one holds the “Head Judge” role yet. Grant it from access & permissions.'}</p>}</label>}
   <label className="block"><span className="text-[10px] font-black text-[#646965]">{ar?'متوسط الجلسة (دقيقة)':'Avg session (min)'}</span><div className="relative mt-2"><Clock3 className="w-4 h-4 absolute start-3 top-1/2 -translate-y-1/2 text-[#6a6f6c] pointer-events-none"/><input type="number" min={1} step="0.5" value={c.averageSessionMinutes} onChange={e=>store.updateCommittee(c.id,{averageSessionMinutes:Math.max(1,Number(e.target.value)||1)})} className="mizan-input mizan-input-icon-start"/></div></label>
  </div>
  <div className="mt-4 flex flex-wrap items-center gap-1.5 text-[10px] font-black">
   <span className={`rounded-full px-2.5 py-1 ${c.judgeIds.length>=required?'bg-[#E7EEE9] text-[#214C40]':'bg-[#F5EDE2] text-[#725630]'}`}>{ar?`${c.judgeIds.length} من ${required} محكمًا`:`${c.judgeIds.length}/${required} judges`}</span>
   <span className="rounded-full bg-[#f1efe9] px-2.5 py-1 text-[#5d645f]">{ar?`${assignedParticipants} موزعون فعليًا`:`${assignedParticipants} assigned`}</span>
   <span className="rounded-full bg-[#f1efe9] px-2.5 py-1 text-[#5d645f]">{ar?`${eligibleParticipants} ضمن الفئات`:`${eligibleParticipants} in scope`}</span>
  </div>
  <div role="tablist" aria-label={ar?'محتوى اللجنة':'Panel content'} className="mt-4 mizan-tabs mizan-tabs-sm">
   <button type="button" role="tab" aria-selected={panelTab==='judges'} onClick={()=>setPanelTab('judges')} title={ar?'أعضاء اللجنة':'Panel members'} aria-label={ar?'أعضاء اللجنة':'Panel members'} className={`mizan-tab !px-3 ${panelTab==='judges'?'is-active':''}`}><UsersRound className="w-4 h-4"/><span>{c.judgeIds.length}</span></button>
   <button type="button" role="tab" aria-selected={panelTab==='categories'} onClick={()=>setPanelTab('categories')} title={ar?'الفئات المسندة':'Assigned categories'} aria-label={ar?'الفئات المسندة':'Assigned categories'} className={`mizan-tab !px-3 ${panelTab==='categories'?'is-active':''}`}><BookMarked className="w-4 h-4"/><span>{c.assignedCategories.length}</span></button>
  </div>
  {panelTab==='judges'&&<div className="mt-3">
   <div className="text-[10px] font-black text-[#646965]">{ar?'أعضاء اللجنة واختصاصاتهم':'Panel judges and specialties'}</div>
   <div className="mt-2 grid gap-2 max-h-72 overflow-auto">{store.judges.map(j=>{const selected=c.judgeIds.includes(j.id)||c.judgeIds.includes(j.userId);const isHead=c.headJudgeId===j.id||c.headJudgeId===j.userId;const activeSpecs=committeeSpecs(c,j);const panels=judgeCommitteeCount(j);return <div key={j.id} className={`rounded-2xl border px-3 py-2.5 ${selected?'border-[#b9ccc3] bg-[#F2F7F4]':'border-[#e4e2db] bg-white'}`}><label className="mizan-consent"><input type="checkbox" checked={selected} onChange={()=>toggleJudge(c.id,j.id)} className="w-4 h-4 accent-[#214C40]"/><span className="min-w-0"><span className="block text-xs font-black truncate">{ar?j.nameArabic:j.name}</span><span className="block text-[9px] text-[#6a706c] mt-0.5">{soloJudge?(ar?'محكّم ورئيس اللجنة':'Judge & chair'):isHead?(ar?'رئيس اللجنة':'Chair'):(ar?'محكم':'Judge')}{selected&&panels>1?(ar?` · في ${panels} لجان`:` · in ${panels} panels`):''}</span></span></label>{selected&&<div className="mt-2 flex flex-wrap gap-1.5">{specialtyOptions.map(opt=><button key={opt.id} type="button" onClick={()=>toggleJudgeSpecialty(c.id,j.id,opt.id)} className={`min-h-8 rounded-full border px-2.5 text-[9px] font-black transition ${activeSpecs.has(opt.id)?'border-[#214C40] bg-[#E7EEE9] text-[#214C40]':'border-[#dedbd2] bg-white text-[#636965]'}`}>{opt.label}</button>)}</div>}</div>})}{!store.judges.length&&<div className="rounded-xl bg-[#F5EDE2] p-3 text-xs font-bold text-[#725630]">{ar?'لا يوجد محكمون بعد. أضف المحكمين من إدارة الفريق ثم عد للتوزيع.':'No judges yet.'}</div>}</div>
  </div>}
  {panelTab==='categories'&&<div className="mt-3">
   <div className="text-[10px] font-black text-[#646965]">{ar?'الفئات المسندة لهذه اللجنة':'Assigned categories'}</div>
   <div className="mt-2 flex flex-wrap gap-2">{store.competition.categories.map(cat=>{const selected=c.assignedCategories.includes(cat.id);return <label key={cat.id} className={`mizan-consent rounded-full border px-3 py-2 ${selected?'border-[#b9ccc3] bg-[#E7EEE9] text-[#214C40]':'border-[#e0ded7] bg-white text-[#5e6561]'}`}><input type="checkbox" checked={selected} onChange={()=>toggleCategory(c.id,cat.id)} className="w-4 h-4 accent-[#214C40]"/><span className="text-[10px] font-black">{ar?cat.nameArabic:cat.name}</span></label>})}</div>
   <div className="mt-3 text-[10px] leading-5 text-[#6a706c]">{ar?'المتسابق يُوجّه فقط إلى لجنة تشمل فئته ولا يوجد فيها تعارض صريح مع أحد المحكمين.':'Participants route only to panels covering their category and without hard judge conflicts.'}</div>
  </div>}
 </article>;
};

const ResultsView=({store,ar}:{store:Store;ar:boolean})=>{const policy=getCompetitionPolicy(store.competition);
 /* الختم قد يُرفض لسبب لا يعرفه من ضغط الزر — فيُقال، ولا يُترك الزر يبتلع الرفض. */
 const [sealNote,setSealNote]=useState('');
 /* الختم إجراء لا رجعة فيه ويستغرق رحلة إلى الخادم: بلا حارس انشغال يبقى الزر قابلًا للضغط
    مرتين طوال الرحلة، وبلا جملة عند الرفض يبدو الضغط كأنه لم يقع. */
 const [sealBusy,setSealBusy]=useState(false);
 const sealNow=async()=>{setSealBusy(true);setSealNote('');try{const out=await store.sealResults();setSealNote(sealFailureLabel(out as {sealed?:boolean;reason?:string;message?:string},ar))}finally{setSealBusy(false)}}; const pending=store.appeals.filter(a=>a.status==='submitted'||a.status==='under_review').length; const allSealed=store.results.length>0&&store.results.every(r=>r.status==='sealed'||r.status==='published');return <div className="space-y-4"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="mizan-kicker">{ar?'النتائج':'RESULTS'}</div><h1 className="text-3xl font-black mt-1">{ar?'اعتماد، ختم، نشر':'Approve · seal · publish'}</h1><p className="text-sm text-[#636965] mt-2">{ar?`الإظهار: ${uiToken(policy.results.visibility,true)}`:`Visibility: ${uiToken(policy.results.visibility,false)}`}</p></div><div className="flex gap-2"><Button variant="outline" disabled={sealBusy} onClick={()=>void sealNow()} icon={<LockKeyhole className="w-4 h-4"/>}>{sealBusy?(ar?'جارٍ الختم…':'Sealing…'):policy.results.requireDualApprovalToSeal?<>{ar?'اعتماد الختم ':'Seal approval '}<Ratio value={new Set(store.sealApprovals.map(a=>a.actorId)).size} of={2}/></>:(ar?'ختم':'Seal')}</Button><Button disabled={!allSealed} onClick={()=>store.publishResults()}>{ar?'نشر':'Publish'}</Button></div></div>{sealNote&&<div role="status" className="rounded-xl bg-[#F5EDE2] text-[#7a5a2f] p-3 text-xs font-bold leading-5">{sealNote}</div>}{pending>0&&<div className="rounded-xl bg-[#F2EADC] text-[#725630] p-3 text-xs font-bold">{ar?`${pending} اعتراضات تحتاج حسمًا قبل الإغلاق`:`${pending} appeals require resolution before closure`}</div>}<div className="mizan-surface overflow-hidden"><div className="divide-y divide-[#e5e3dc]">{[...store.results].sort((a,b)=>a.rank-b.rank).map(r=><div key={r.id} className="p-4 sm:px-5 flex items-center gap-4"><div className="w-10 text-2xl font-black text-[#214C40]">{r.rank||'—'}</div><div className="min-w-0 flex-1"><div className="font-bold text-sm truncate">{ar?r.participantNameArabic:r.participantName}</div><div className="text-[11px] text-[#656b66] mt-1">{(ar?(r.categoryNameArabic||r.categoryName):r.categoryName)||(ar?'فئة محذوفة':'Removed category')} · {localizedCountry(r.country,ar)}</div></div><div className="font-black tabular-nums">{r.finalScore.toFixed(2)}</div><Badge variant={r.status==='sealed'||r.status==='published'?'emerald':'neutral'}>{uiToken(r.status,ar)}</Badge><button disabled={!['sealed','published'].includes(r.status)} onClick={()=>store.generateCertificate(r.id)} title={ar?'إصدار شهادة':'Issue certificate'} aria-label={ar?'إصدار شهادة':'Issue certificate'} className="w-11 h-11 rounded-xl grid place-items-center hover:bg-[#efede7] text-[#59615c] disabled:opacity-30"><Award className="w-4 h-4"/></button></div>)}</div></div><div className="text-xs text-[#656b66]">{store.certificates.length} {ar?'شهادة':'certificates'} · {store.auditLogs.length} {ar?'حدث تدقيق':'audit events'}</div></div>};

/* نوع الحقل كان يُطبع بمعرّفه البرمجي (text/email/select) تحت تسمية عربية. */
const fieldTypeLabel=(t:string,ar:boolean)=>ar?(({text:'نص',textarea:'نص طويل',email:'بريد إلكتروني',phone:'رقم هاتف',tel:'رقم هاتف',date:'تاريخ',number:'رقم',select:'اختيار من قائمة',checkbox:'خانة اختيار',file:'ملف',country:'دولة'} as Record<string,string>)[t]||'نص'):t;
const RegistrationFieldRow=({f,ar,onVisible,onRequired}:{f:RegistrationFieldDefinition;ar:boolean;onVisible:(v:boolean)=>void;onRequired:(v:boolean)=>void})=><div className="py-3 grid grid-cols-[1fr_auto] items-center gap-3"><div><div className="text-sm font-bold">{ar?f.labelArabic:f.labelEnglish}</div><div className="text-[11px] text-[#666b67]">{fieldTypeLabel(f.type,ar)}</div></div><div className="flex gap-1"><Chip active={f.visible} onClick={()=>onVisible(!f.visible)}>{f.visible?(ar?'ظاهر':'Visible'):(ar?'مخفي':'Hidden')}</Chip><Chip active={f.required} amber onClick={()=>onRequired(!f.required)}>{f.required?(ar?'إلزامي':'Required'):(ar?'اختياري':'Optional')}</Chip></div></div>;
const Toggle=({value,onChange,label}:{value:boolean;onChange:(v:boolean)=>void;label:string})=><button type="button" onClick={()=>onChange(!value)} className="w-full flex items-center justify-between gap-4 py-3 text-start border-b border-[#e7e5de] last:border-0"><span className="text-sm font-semibold text-[#303733]">{label}</span><span className={`relative w-10 h-6 rounded-full transition ${value?'bg-[#214C40]':'bg-[#d6d4cd]'}`}><span className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow-sm transition ${value?'end-1':'end-5'}`}/></span></button>;
const Chip=({active=false,amber=false,onClick,children}:{active?:boolean;amber?:boolean;onClick:()=>void;children:React.ReactNode})=><button type="button" onClick={onClick} className={`px-2.5 py-1.5 rounded-lg text-[11px] font-bold ${active?(amber?'bg-[#F2EADC] text-[#7d5e34]':'bg-[#E7EEE9] text-[#214C40]'):'bg-[#efede7] text-[#777]'}`}>{children}</button>;
const NavButton=({active,onClick,icon:Icon,label}:{active:boolean;onClick:()=>void;icon:React.ComponentType<{className?:string}>;label:string})=><button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-bold transition ${active?'bg-[#214C40] text-white':'text-[#626a65] hover:bg-[#efede7] hover:text-[#303733]'}`}><Icon className="w-4 h-4"/><span>{label}</span></button>;
const TinySelect=({value,onChange,children}:{value:string;onChange:(v:string)=>void;children:React.ReactNode})=><select value={value} onChange={e=>onChange(e.target.value)} className="mizan-input text-sm font-semibold text-[#303733]">{children}</select>;
const SectionTitle=({title,subtitle}:{title:string;subtitle:string})=><div><h2 className="text-xl font-black text-[#202622]">{title}</h2><p className="text-xs text-[#646965] mt-1.5 max-w-2xl">{subtitle}</p></div>;
const Control=({label,children}:{label:string;children:React.ReactNode})=><label className="block"><span className="block text-xs font-black text-[#686f6a] mb-2">{label}</span>{children}</label>;
const TextControl=({label,value,onChange,type='text',kind}:{label:string;value:string;onChange:(v:string)=>void;type?:string;kind?:'arabic'|'latin'})=><Control label={label}><input type={type} value={value} onChange={e=>onChange(e.target.value)} lang={kind==='arabic'?'ar':kind==='latin'?'en':undefined} data-mizan-kind={kind} dir={kind==='latin'||type==='email'?'ltr':undefined} className="mizan-input text-sm font-semibold"/></Control>;
const NumberControl=({label,value,onChange,step=1,min=0,max=9999}:{label:string;value:number;onChange:(v:number)=>void;step?:number;min?:number;max?:number})=>{const clamp=(v:number)=>Math.max(min,Math.min(max,Number.isFinite(v)?v:min));return <Control label={label}><div className="mizan-control relative flex items-center"><button type="button" aria-label={`إنقاص ${label}`} disabled={value<=min} onClick={()=>onChange(clamp(value-step))} className="mizan-step-btn"><span className="text-xl leading-none" aria-hidden="true">−</span></button><input type="number" inputMode={step<1?'decimal':'numeric'} step={step} min={min} max={max} value={value} onChange={e=>onChange(clamp(Number(e.target.value)))} className="mizan-number-input flex-1 min-w-0 px-1 text-center text-base font-black outline-none bg-transparent tabular-nums"/><button type="button" aria-label={`زيادة ${label}`} disabled={value>=max} onClick={()=>onChange(clamp(value+step))} className="mizan-step-btn"><Plus className="w-4 h-4"/></button></div></Control>};
const MetricCard=({icon:Icon,value,label}:{icon:React.ComponentType<{className?:string}>;value:number|string;label:string})=><div className="mizan-surface p-4 sm:p-5 min-w-0"><Icon className="w-4 h-4 text-[#2F6555] mb-4"/><div className="text-2xl sm:text-3xl font-black truncate">{value}</div><div className="text-xs text-[#636864] mt-1 truncate">{label}</div></div>;
const MiniMetric=({value,label}:{value:string;label:string})=><div className="rounded-xl bg-[#f1efe9] p-4"><div className="text-xl font-black">{value}</div><div className="text-[11px] text-[#636965] mt-1">{label}</div></div>;
const workflowLabel=(id:string,ar:boolean)=>({register:ar?'التسجيل':'Register',verify:ar?'التحقق':'Verify',approve:ar?'الاعتماد':'Approve',schedule:ar?'الجدولة':'Schedule',notify:ar?'الإشعار':'Notify',checkin:ar?'الحضور':'Check-in',route:ar?'التوجيه':'Route',draw:ar?'السحب':'Draw',judge:ar?'التحكيم':'Judge',integrity:ar?'النزاهة':'Integrity',seal:ar?'الختم':'Seal',publish:ar?'النشر':'Publish',certificate:ar?'الشهادة':'Certificate'} as Record<string,string>)[id]||id;
const statusLabel=(s:string,ar:boolean)=>({submitted:ar?'مرسل':'Submitted',under_review:ar?'مراجعة':'Review',approved:ar?'مقبول':'Approved',checked_in:ar?'حضر':'Checked in',in_queue:ar?'ينتظر':'Waiting',in_session:ar?'داخل اللجنة':'In session',tested:ar?'اختبر':'Tested',appealed:ar?'اعتراض':'Appeal',certified:ar?'معتمد':'Certified',draft:ar?'مسودة':'Draft',rejected:ar?'مرفوض':'Rejected',registered:ar?'مسجّل':'Registered',withdrawn:ar?'منسحب':'Withdrawn',absent:ar?'غائب':'Absent',no_show:ar?'لم يحضر':'No show',disqualified:ar?'مستبعد':'Disqualified',sealed:ar?'مختوم':'Sealed',published:ar?'منشور':'Published'} as Record<string,string>)[s]||(ar?'—':s);
